import { useState, useCallback } from "react";

// ── DATA ──────────────────────────────────────────────────────────────────────
const D1 = [
{n:1,t:"Swaroopa Mahathvam",kv:"1.8",vt:"namrāṇāṃ sannidhatte — You always appear before those who bow to You, granting even unasked boons. You are the Parijata tree available to all, oh Hari!",q:"What does Bhattathiri compare the Lord at Guruvayur to?",o:["The Ganga river","The Parijata wish-fulfilling tree","Mount Meru","The Sudarshana chakra"],a:1,vs:"नम्राणां सन्निधत्ते सततमपि तवानन्तसौख्यप्रदाता पारिजातः स्वधर्मात् प्रभवति न तु पार्श्वे विहाराय ते।",exp:"Bhattathiri calls Guruvayurappan the Parijata tree — the divine wish-fulfilling tree of heaven — available to all who approach with devotion.",fact:"Dasakam 1 establishes that the Lord at Guruvayur is pure Sattva — untouched by Rajas and Tamas — which is why His presence is so powerfully purifying."},
{n:2,t:"Swarupa Madhurya",kv:"2.1",vt:"sāndrānanda — The form of the Lord shines with concentrated bliss: dark as a rain-cloud, eyes like lotus petals, the Kaustubha gem blazing on His chest.",q:"What gem from the churning of the ocean adorns the Lord's chest?",o:["Syamantaka","Kaustubha","Chintamani","Padmaraga"],a:1,vs:"सान्द्रानन्दावबोधात्मकमनुपमितं कालदेशावधिभ्यां निर्मुक्तं नित्यमुक्तं निगमशतसहस्रेण निर्भास्यमानम्।",exp:"The Kaustubha gem, which emerged during the Samudra Manthan, adorns the Lord's chest. It symbolizes pure, luminous consciousness that shines at the heart of all creation.",fact:"The Srivatsa mark on the Lord's chest is where Lakshmi permanently resides — showing that Fortune is inseparable from the Lord."},
{n:3,t:"Bhakta Swarupa",kv:"3.10",vt:"āyurarōgyaṃ — Grant me health and long life, O Lord of Guruvayur, so I may sing Your glories. Drive away the disease that torments this body.",q:"Bhattathiri composed Narayaneeyam while suffering from what ailment?",o:["Blindness","Paralysis (rheumatism)","Deafness","Fever"],a:1,vs:"आयुरारोग्यसौख्यं परमपि च पदं देहि देहीश मह्यं त्वत्पादाम्भोरुहेभ्यो न च कुचरपथे धावतां मे मनोऽस्तु।",exp:"Meppathur Narayana Bhattathiri was afflicted with severe rheumatism. Unable to move, he composed the Narayaneeyam at Guruvayur as an offering to the Lord, praying for relief.",fact:"Tradition holds that when Bhattathiri completed the 100th Dasakam, the Lord appeared and his disease was cured — making Narayaneeyam both a scripture and a miracle."},
{n:4,t:"Yoga Abhyasa",kv:"4.1",vt:"kalyatāṃ mama — O bestower of auspiciousness, grant me health so I may master the eight-limbed yoga and quickly attain Your grace.",q:"How many limbs does Ashtanga Yoga have?",o:["Four","Six","Eight","Ten"],a:2,vs:"कल्यतां मम कल्याण-निधे कल्याणवर्धन त्वत्पादसेवासुलभा परा भक्तिर्भवेन्मम।",exp:"Ashtanga Yoga has eight limbs: Yama, Niyama, Asana, Pranayama, Pratyahara, Dharana, Dhyana, and Samadhi. All paths of yoga ultimately lead to the Lord.",fact:"Dasakam 4 is one of the longest Dasakams in Narayaneeyam. Bhattathiri describes the entire Yoga Shastra here to show that all paths of yoga ultimately lead to the Lord."},
{n:5,t:"Virat Purusha Utpatti",kv:"5.7",vt:"tvayi vibhāti — In You the entire universe shines like a city reflected in a mirror. You are the witness, the substratum on which all creation dances.",q:"What metaphor describes how the universe exists within the Lord?",o:["A dream within sleep","A city reflected in a mirror","A wave in the ocean","A flame in the wind"],a:1,vs:"त्वयि विभाति जगत् त्वं विभासि जगति जगन्न तत्त्वतस्ते विभागः।",exp:"The universe exists in the Lord like a city reflected in a mirror — the reflection is real to the viewer but has no independent existence apart from the mirror. This illustrates Maya.",fact:"The Virat Purusha is the cosmic body of the Lord — the entire universe is His form. When we see the cosmos, we are literally seeing the body of God."},
{n:6,t:"Virat Swarupa Varnana",kv:"6.1",vt:"pādau yasya — Whose feet are the earth, whose navel is the sky, whose eyes are the sun and moon — that Virat Purusha is You, O Lord of Guruvayur.",q:"In the Virat Swarupa description, what are identified as the Lord's two eyes?",o:["Stars and planets","Sun and Moon","Fire and water","Sky and earth"],a:1,vs:"पादौ यस्य भूमिर्नभो यस्य नाभिर् ज्योतीरूपो यस्य चक्षुस्तु भानुः।",exp:"In the Virat Purusha description, the Sun is the Lord's right eye and the Moon is His left eye. This is found in the Purusha Sukta of the Rig Veda and elaborated in Narayaneeyam.",fact:"This vision — that the cosmos is the Lord's body — transforms how a devotee sees the world. Every sunrise becomes darshan of the Lord's eye."},
{n:7,t:"Srishti Krama",kv:"7.5",vt:"ambhasi śayānaṃ — Reclining on the causal waters, the great serpent Ananta as Your bed, the lotus sprouting from Your navel — in this form You hold all creation within.",q:"From where does the lotus sprout that contains Brahma?",o:["From the cosmic ocean floor","From Vishnu's navel","From Shiva's third eye","From Saraswati's hand"],a:1,vs:"अम्भसि शयानं भुजगशयने तं नाभिसरोजभवब्रह्माण्डमूलम्।",exp:"A lotus sprouts from Vishnu's navel as He reclines on Ananta on the cosmic ocean. Brahma is born in this lotus and is tasked with creating the universe.",fact:"The image of Vishnu reclining on Ananta is called Anantashayana. Ananta means infinite — the Lord rests on infinity itself, showing His nature beyond time and space."},
{n:8,t:"Pralaya and Birth of Brahma",kv:"8.3",vt:"padmabhavaḥ — When Brahma dove into the lotus stalk seeking the origin and could not find it, You appeared before him and commanded him to create.",q:"What did Brahma do before he could begin creating?",o:["He performed 1000 years of penance","He dove into the lotus stalk to find its source but failed","He consulted the four Vedas","He sought Shiva's permission"],a:1,vs:"पद्मभवः खलु पद्मे विरिञ्चः पद्मनाभं त्वां ददर्श स्तुतिं च।",exp:"Brahma dove down the lotus stalk trying to find its root. He could not find it. Only then did Vishnu appear and reveal Himself as the source, instructing Brahma to create.",fact:"This story shows that even the creator Brahma cannot find God through his own intellectual effort — God reveals Himself when He chooses, to those who are ready."},
{n:9,t:"Nava Yogendra Upadesha",kv:"9.4",vt:"śravaṇaṃ kīrtanaṃ — Hearing, chanting, remembering, serving the feet, worshipping, saluting, being a servant, being a friend, and self-surrender — these nine forms of devotion are the supreme path.",q:"The nine forms of Bhakti were taught by the nine Yogendras to which king?",o:["King Ambarisha","King Parikshit","King Nimi","King Yayati"],a:2,vs:"श्रवणं कीर्तनं विष्णोः स्मरणं पादसेवनम्। अर्चनं वन्दनं दास्यं सख्यमात्मनिवेदनम्।।",exp:"The nine Yogendras (sons of King Rishabha) taught the Navavidha Bhakti to King Nimi of the Videha kingdom. This teaching is one of the most celebrated passages in the Bhagavata Purana.",fact:"The nine forms of Bhakti begin with Shravana (hearing) and end with Atmanivedana (total self-surrender). Dushyanth Sridhar emphasizes that all nine are valid paths — one need only master one fully."},
{n:10,t:"Bhagavan Mahima",kv:"10.8",vt:"tvaṃ śaraṇam — You alone are my refuge, O Guruvayurappa. Even Brahma and Shiva bow before You. Remove all my afflictions and grant me the vision of Your lotus face.",q:"In Dasakam 10, who declares the Lord's glory and praises devotion as the highest path?",o:["Shuka Muni","Narada","Vyasa","Vasishtha"],a:1,vs:"त्वं शरणं त्वं शरणं महेश त्वं शरणं देव जगत्प्रणेतः।",exp:"Narada Muni declares the Lord's supreme glory in Dasakam 10. Having received the grace of the Lord in his previous birth as a maidservant's son, Narada became the greatest devotee-sage and teacher of Bhakti.",fact:"Narada's previous life story — as a poor boy who served sages — is one of the most moving in the Bhagavata. Even a single meal of the sages' remnants transformed him into an eternal devotee."},
{n:11,t:"Varaha Avatara",kv:"11.5",vt:"kṣoṇīṃ niṣkramya — Lifting the earth on Your tusk, dripping with the cosmic waters, You emerged like the sun rising from the ocean, O Varaha.",q:"Who had stolen the earth and where had it been hidden?",o:["Ravana, hidden in Lanka","Hiranyaksha, hidden in the cosmic ocean","Kamsa, hidden underground","Narakasura, in Pragjyotisha"],a:1,vs:"क्षोणीं निष्क्रम्य तोयाद्धृतवसुमथ ते यज्ञवाराहमूर्ते दंष्ट्राग्रे विश्वसारे जलधिजलधरश्याम धन्यः स दैत्यः।",exp:"The demon Hiranyaksha stole the earth (Bhudevi) and plunged with her into the depths of the cosmic ocean. Vishnu took the form of a gigantic boar, dove into the ocean, slew Hiranyaksha, and lifted the earth on His tusk.",fact:"The Varaha form is both terrifying and tender — a massive cosmic boar that gently lifts the earth goddess like a lotus petal on its tusk. This contrast is central to the avatara's beauty."},
{n:12,t:"Kapila Avatara",kv:"12.6",vt:"bhakti-yogena — By the yoga of devotion, O Kapila, You taught Your mother the means of liberation. She crossed the ocean of birth and death through Your grace.",q:"To whom did the Kapila avatara teach Sankhya philosophy and Bhakti yoga?",o:["To his father Kardama Muni","To his mother Devahuti","To the four Kumaras","To King Janaka"],a:1,vs:"भक्तियोगेन मनसि सम्यक् प्रणिहिते यो भेदमजहात्।",exp:"Kapila, born as the son of Kardama Muni and Devahuti, taught the Sankhya philosophy and path of Bhakti to his own mother Devahuti. This teaching in the Bhagavata's third canto is one of the most profound philosophical discourses.",fact:"Devahuti was attached to her husband and then to her son. Kapila's teaching gently freed her from both attachments. She ultimately attained liberation."},
{n:13,t:"Narada Avatara and Daksha",kv:"13.3",vt:"haryaśvāḥ — When the Haryashvas were about to create progeny, Narada taught them the truth of the Self. They never returned — attaining liberation.",q:"Why did Daksha curse Narada?",o:["For stealing the Vedas","For advising his sons to seek liberation instead of creating progeny","For disturbing his yajna","For marrying his daughter"],a:1,vs:"हर्यश्वाः पुत्रसहस्रं तव नारदशापाद् ययुर्न पुनर्भवम्।",exp:"Daksha had 10,000 sons to help populate the world. Narada advised both groups to seek liberation first, and they all left. An enraged Daksha cursed Narada to wander perpetually without rest.",fact:"Narada accepted the curse gracefully — for a devotee, wandering the worlds singing the Lord's name is not a punishment but a blessing! The curse became his eternal pilgrimage."},
{n:14,t:"Nara-Narayana Avatara",kv:"14.4",vt:"ūrūdbhavāṃ — When Indra sent celestial dancers to disturb the penance, You manifested from Your own thigh a beauty surpassing all apsaras — the divine Urvashi.",q:"Where did the twin sages Nara and Narayana perform their penance?",o:["Rishikesh","Badarikashrama (Badrinath)","Kashi","Tirupati"],a:1,vs:"ऊरूद्भवां मनोजं तव वपुः स्वयं विचित्रं विबुधैर् नुतं सदा।",exp:"Nara and Narayana performed their intense penance at Badarikashrama, the holy place in the Himalayas known today as Badrinath. This is why Badrinath is one of the most sacred pilgrimage sites in India.",fact:"The Lord is still believed to reside at Badrinath as Nara-Narayana. Bhattathiri says these twin sages are eternal — Nara continues as Arjuna and Narayana as Krishna in the Dwapara Yuga."},
{n:15,t:"Rishabha and Bharata",kv:"15.5",vt:"jaDabharataḥ — Though born as a brahmin, Jadabharata acted as if ignorant. Carried as a palanquin-bearer, he taught King Rahugana the supreme truth of the Self.",q:"Why was King Bharata (son of Rishabha) reborn as a deer?",o:["As punishment for abandoning his kingdom","Because of his excessive attachment to a fawn he had rescued","Because he had not performed enough rituals","Because he angered a sage"],a:1,vs:"जडभरतो भगवद्भक्तो राहूगणाय ततो ज्ञानमुपादिशत्।",exp:"Bharata became deeply attached to a deer fawn he had rescued. At the moment of death his mind was on the deer, not on God, so he was reborn as a deer — demonstrating how even subtle attachment causes rebirth.",fact:"In his life as a deer, Bharata remembered his past lives. He then took birth as Jadabharata and, feigning madness to avoid all attachment, finally attained liberation."},
{n:16,t:"Dhruva Charitra",kv:"16.5",vt:"om namo bhagavate — Narada taught Dhruva the twelve-syllable mantra and the form of Vishnu to meditate upon. The young boy performed tapas so intense that Vishnu Himself appeared.",q:"How old was Dhruva when he went to the forest to perform penance?",o:["Ten years old","Five years old","Twelve years old","Seven years old"],a:1,vs:"ॐ नमो भगवते वासुदेवाय इति द्वादशवर्णो मन्त्रो ध्रुवाय दत्तः।",exp:"Dhruva was only five years old when his stepmother Suruchi insulted him. His mother Suniti guided him to seek the Lord. Despite his young age, his determination was unshakeable.",fact:"Dhruva's penance was so intense that when he stood on one foot and controlled his breath, the gods could not breathe — the universe was affected. Vishnu had to appear to restore cosmic balance."},
{n:17,t:"Prithu Avatara",kv:"17.6",vt:"dharā dohena — When Prithu threatened to pierce the earth-cow, she yielded and was milked of all crops, herbs, and prosperity that sustain all living beings.",q:"King Prithu is credited with originating what practice?",o:["Building cities","Agriculture and cultivation of crops","Writing of scriptures","Performing fire sacrifices"],a:1,vs:"धरा दोहेन सर्वौषधि- बीजानि पृथिव्यामदात्।",exp:"Before Prithu, the earth did not yield crops freely. Prithu compelled the earth (Prithvi) to give her produce, essentially originating agriculture. The word Prithvi (earth) itself comes from Prithu's name.",fact:"Prithu was the first consecrated king — his coronation established the ideal of sacred kingship. He is said to have leveled mountains to make the earth flat and cultivable."},
{n:18,t:"Gajendra Moksha",kv:"18.8",vt:"tvāṃ aham — I am Yours, O Lord! Gajendra's surrender — his trunk raised, his voice broken, his pride gone — moved the Lord who rushed without even donning His ornaments.",q:"For how long was Gajendra locked in battle with the crocodile?",o:["100 years","1000 years","One day","Seven days"],a:1,vs:"त्वामहं शरणं गतो गजेन्द्रमोक्षणाय नमः।",exp:"Gajendra and the crocodile battled for 1000 years. The mighty elephant king gradually weakened while the crocodile, in its element, did not tire. Exhausted and humbled, Gajendra finally called out to the Lord.",fact:"The crocodile was actually the gandharva Huhu cursed by sage Devala. When Vishnu's Sudarshana severed his snout, Huhu was liberated too. Gajendra Moksha thus freed two souls simultaneously."},
{n:19,t:"Samudra Manthan Part 1",kv:"19.5",vt:"kūrmarūpeṇa — Assuming the form of a tortoise, You bore the weight of Mount Mandara on Your back. As the mountain spun, You felt pleasurable friction and smiled inwardly.",q:"What was used as the churning rope during the Samudra Manthan?",o:["A golden chain from heaven","The serpent Vasuki","Brahma's sacred thread","The river Ganga"],a:1,vs:"कूर्मरूपेण धृत्वा मन्दरं मधुसूदन।",exp:"The great serpent Vasuki was used as the churning rope, wrapped around Mount Mandara. The gods held Vasuki's tail and the demons held his head, churning the cosmic ocean.",fact:"Vishnu as Kurma not only supported Mandara from below but also energized both the gods and demons from within during the churning — a beautiful secret in the Bhagavata."},
{n:20,t:"Samudra Manthan Part 2",kv:"20.6",vt:"mohinyā — Taking the enchanting Mohini form, You distributed the nectar only to the gods. When Rahu sat among the devas, the Sun and Moon revealed him — and You severed his head.",q:"Who drank the Halahala (deadly poison) that emerged during the churning?",o:["Vishnu","Brahma","Shiva","Indra"],a:2,vs:"मोहिन्या रूपेण हरिस् सुरेभ्यो ददौ सुधाम्।",exp:"When the deadly Halahala poison emerged and threatened all creation, Shiva drank it at Parvati's urging. Parvati held Shiva's throat to prevent the poison from going down — this is why Shiva is called Neelakantha (blue-throated).",fact:"The Halahala was so potent that drops that fell on earth became scorpions and poisonous plants. Shiva's act of drinking it is one of the greatest acts of sacrifice in all of Hindu scripture."},
{n:21,t:"Ajamila Charitra",kv:"21.4",vt:"nāmoccāraṇa — Even calling Narayana at the moment of death — though meant for his son — was enough to drive away Yama's messengers. Such is the infinite power of Your name.",q:"Why did the Vishnudutas intervene when Yamadutas came to take Ajamila?",o:["Because Ajamila was a brahmin","Because Ajamila had uttered the name Narayana at the moment of death","Because Ajamila had performed a great sacrifice","Because Ajamila's son prayed for him"],a:1,vs:"नामोच्चारणमात्रेण यमदूतास्त्रासिताः।",exp:"Even though Ajamila called Narayana intending his youngest son, the Lord's name carries infinite power regardless of intent. The Vishnudutas argued that this utterance had wiped away all his sins.",fact:"The debate between Vishnudutas and Yamadutas in Dasakam 21 is one of the most philosophically rich passages in the Bhagavata — covering karma, grace, the power of the Name, and the nature of liberation."},
{n:22,t:"Daksha Yajna",kv:"22.7",vt:"satī deha — When Sati heard her father insult her husband Shiva, she could bear it no more. Renouncing her body born of Daksha, she entered the fire, leaving Shiva in boundless grief.",q:"What happened to Daksha's head after Sati's self-immolation?",o:["He was imprisoned","Veerabhadra cut off his head; later he was revived with a goat's head","He was cursed to be reborn","He was banished from heaven"],a:1,vs:"सती देहं त्यजन्ती दक्षस्य यज्ञे ममार।",exp:"Shiva created the terrible Veerabhadra who stormed the yajna and cut off Daksha's head. Later, when order was restored by Vishnu, Daksha was revived but given the head of a goat.",fact:"This story shows that disrespecting a devotee's spouse is equivalent to disrespecting the devotee — and disrespecting Shiva, who is Vishnu's greatest devotee, invites the Lord's own displeasure."},
{n:23,t:"Ganga Avataran",kv:"23.3",vt:"viṣṇupādābjā — Born from the lotus feet of Vishnu, received by Brahma, caught by Shiva in His matted locks, the sacred Ganga purifies all who touch her waters.",q:"King Bhagiratha brought the Ganga to earth to achieve what purpose?",o:["To irrigate his kingdom","To liberate the souls of his 60,000 ancestors burned by Kapila Muni's wrath","To defeat his enemies","To please Vishnu"],a:1,vs:"विष्णुपादाब्जसम्भूता गङ्गा पावनतमा नदी।",exp:"King Sagara's 60,000 sons had been reduced to ashes by the wrath of sage Kapila. Their souls could not attain liberation without the purifying waters of the Ganga. Bhagiratha performed intense penance to bring Ganga to earth.",fact:"The Ganga's descent — from Vishnu's feet to Brahma's pot to Shiva's locks to earth — took the combined efforts of three great ancestors: Sagara, Ansuman, and finally Bhagiratha. His name gave us the phrase Bhagirath prayatna (heroic effort)."},
{n:24,t:"Prahlada Charitra Part 1",kv:"24.5",vt:"sthāvara jaṅgama — The Lord pervades all — the moving and unmoving. Prahlada taught this truth fearlessly in the very court of his demon father.",q:"What happened when teachers Shanda and Amarka tried to educate Prahlada in demon ways?",o:["They succeeded completely","They completely failed as Prahlada kept teaching Vishnu Bhakti to his classmates","Shukracharya had to replace them","Prahlada was imprisoned"],a:1,vs:"स्थावरं जङ्गमं व्याप्तं किंचित् सर्वत्र ते हरिः।",exp:"Hiranyakashipu sent Prahlada to the gurukul of Shanda and Amarka. Instead, Prahlada turned his classmates into Vishnu devotees, teaching them the nine forms of Bhakti. The teachers despaired and reported this to the king.",fact:"Prahlada's teaching to his classmates is called Prahlada Gita — a child teaching other children about the Lord. When the guru is the Lord Himself, age means nothing."},
{n:25,t:"Prahlada Charitra Part 2",kv:"25.8",vt:"stambhāt — When the demon king struck the pillar asking where is your Vishnu, the Lord burst forth — half-lion, half-man — and slew Hiranyakashipu on His lap at twilight.",q:"How did Narasimha fulfill every clause of Hiranyakashipu's boon?",o:["By being more powerful than any boon","By being half-man half-lion, at the threshold, at dusk, on His lap, with nails — satisfying every condition simultaneously","Because Prahlada prayed specifically","Because the boon had expired"],a:1,vs:"स्तम्भात् नृसिंहो जातः हिरण्यकशिपुं हन्तुम्।",exp:"Hiranyakashipu's boon said he could not be killed by man or animal, inside or outside, day or night, on earth or sky, by any weapon. Narasimha fulfilled every condition simultaneously, showing no ego-driven boon can withstand divine will.",fact:"This story is the ultimate demonstration that no ego-driven boon can protect one from the Lord. The very creativity of the boon's conditions became the blueprint for how it would be circumvented."},
{n:26,t:"Vamana Avatara",kv:"26.6",vt:"trivikramā — With the first step You covered the earth, with the second the heavens. For the third, noble Bali offered his own head. Brahma washed Your foot and that water became the sacred Ganga.",q:"Who warned Mahabali not to grant Vamana's request?",o:["Brahma","Shukracharya, who recognized Vamana as Vishnu in disguise","Ravana","Prahlada"],a:1,vs:"त्रिविक्रमाय नमस्ते त्रिलोकव्यापिने नमः।",exp:"Shukracharya, the preceptor of the demons, recognized that Vamana was Vishnu in disguise and warned Bali not to grant the boon. But Bali declared it was an honor to give to Vishnu and a promise to a brahmin could not be broken.",fact:"Bali's greatness lies in his knowing surrender. He knew Vamana was Vishnu, he knew he would lose everything — and he gave joyfully. This is the highest form of charity: giving to God what was never truly yours."},
{n:27,t:"Matsya Avatara",kv:"27.5",vt:"matsyarūpa — Taking the form of a golden fish, You protected the Vedas stolen by Shankhasura, guided Manu's boat through the deluge, and preserved the seeds of all creation.",q:"What did the fish instruct King Satyavrata (Manu) to collect on his boat?",o:["Gold and jewels for the next age","Seeds of all plants, pairs of all animals, and the seven sages","Only his family and servants","Only the scriptures"],a:1,vs:"मत्स्यरूपेण तोयेऽवतीर्य वेदान् रक्षित्वा मनुमुद्धरस्त्वम्।",exp:"The fish (Vishnu) instructed Manu to build a great boat and load it with seeds of all plants, pairs of all animals, and the seven great sages (Saptarishis) — preserving life during the great deluge.",fact:"The demon Shankhasura stole the Vedas from Brahma while he slept. Vishnu as Matsya killed Shankhasura and recovered the Vedas — protecting both cosmic knowledge and cosmic life simultaneously."},
{n:28,t:"Hayagriva and Hamsa Avatara",kv:"28.4",vt:"haṃsarūpa — As the divine Swan, You appeared before Brahma. When they asked Who are You, You smiled: the one who truly knows the Self has no question left.",q:"What did the demon Hayagriva steal?",o:["The Sudarshana chakra","The Vedas from Brahma while he slept","The nectar from the gods","The Kaustubha gem"],a:1,vs:"हंसरूपेण तत्त्वं ब्रह्मणे त्वमुपादिशः।",exp:"The demon Hayagriva stole the Vedas from Brahma when the creator momentarily dozed off. Vishnu took the horse-headed form, slew the demon, and restored the Vedas to Brahma.",fact:"The Hamsa (swan) avatar taught Brahma and the four Kumaras the highest Vedantic truth. The swan's ability to separate milk from water symbolizes viveka (discrimination) — separating the eternal from the temporary."},
{n:29,t:"Churning — Lakshmi Vivaha",kv:"29.5",vt:"varalakṣmī — When Lakshmi emerged bearing a lotus garland, all the gods hoped she would choose them. But She placed the garland on Your chest alone — for where else would Fortune dwell?",q:"What does Lakshmi residing on Vishnu's chest symbolize?",o:["It is an ornament He wears","Fortune is inseparable from the Lord — where He is, abundance follows","It is a mark of victory over the demons","She rests there to guard the Kaustubha gem"],a:1,vs:"वरलक्ष्मीर्वरेण्या त्वत्पदे नित्यवासिनी।",exp:"Lakshmi on Vishnu's chest symbolizes that divine grace and abundance are inseparable from the Lord. A devotee who connects with Vishnu automatically receives Lakshmi's blessings.",fact:"All the gods, gandharvas, and humans were attracted to Lakshmi as she stood with her garland. But she chose Vishnu without hesitation — for she is His eternal Shakti, temporarily separated during creation to create the play of seeking."},
{n:30,t:"Parashurama Avatara",kv:"30.4",vt:"kṣatriyāntaka — Armed with the axe given by Shiva, You as Parashurama rid the earth of arrogant Kshatriyas twenty-one times over — restoring Dharma when warriors became tyrants.",q:"What event directly triggered Parashurama's mission?",o:["A prophecy at his birth","Kartavirya Arjuna stole the Kamadhenu cow; later Kshatriyas killed his father Jamadagni","Parashurama lost a battle","Indra ordered him to do so"],a:1,vs:"क्षत्रियान्तकराय नमो परशुरामाय ते नमः।",exp:"King Kartavirya Arjuna forcibly took the divine Kamadhenu cow from Jamadagni's ashram. Parashurama killed Kartavirya. To avenge their king, the Kshatriyas then killed the unarmed sage Jamadagni — triggering Parashurama's 21-fold cleansing.",fact:"Parashurama received his divine axe from Shiva after intense penance. He is one of the eight Chiranjivis (immortals) in Hindu tradition and is believed to still be alive in the Mahendra mountains."},
{n:31,t:"Rama Avatara Part 1",kv:"31.6",vt:"śivadhanuḥ — When all the kings failed to even lift the bow, You took it up, strung it, and broke it with a thunderous sound. Sita placed the garland and the earth rejoiced.",q:"Who was Ahalya and how was she liberated by Rama?",o:["A demoness who attacked Rama","A sage's wife cursed to become a stone, restored when Rama's foot touched her","A celestial dancer who became Sita's attendant","The wife of King Janaka"],a:1,vs:"शिवधनुर्भञ्जनं कृत्वा सीतां स्वयंवरे लब्धवान् रामः।",exp:"Ahalya, the wife of sage Gautama, had been cursed to lie as a stone. When Rama walked through the ashram and the dust of his foot touched the stone, Ahalya was transformed back.",fact:"The liberation of Ahalya is the first act of grace in Rama's avatara. It establishes the pattern: the Lord's very presence, His footstep, His glance, is enough to purify and liberate."},
{n:32,t:"Rama Avatara Part 2",kv:"32.8",vt:"jāṭāyu — Old Jatayu fought Ravana with every last breath to save Sita. His wings severed, he fell — yet lived long enough to tell Rama where Sita was taken.",q:"What did Rama do for the dying Jatayu that showed extraordinary grace?",o:["Built a temple in his honor","Performed the last rites with his own hands, granting Jatayu liberation","Brought him back to life","Named a mountain after him"],a:1,vs:"जटायुर्मृत्युसमये रामपादं स्मरन् मुक्तः।",exp:"Rama performed the last rites for Jatayu with his own hands, as he would for his own father. He declared that Jatayu, who died protecting Sita, had attained the highest goal.",fact:"Rama could not perform his father Dasharatha's last rites due to his exile. By doing so for Jatayu — a bird — the Lord showed that devotion transcends species, and a faithful death in service earns liberation."},
{n:33,t:"Rama Avatara Part 3",kv:"33.7",vt:"rāvaṇa vadha — Arrow after arrow You fired, severing each head — only for them to grow back. Then Agastya revealed the Aditya Hridayam, and with the Brahmastra, Ravana fell forever.",q:"What did Hanuman find when he located Sita in Lanka?",o:["She had lost all hope","She was in the Ashoka grove under a Simshupa tree, meditating on Rama constantly, surrounded by demonesses","She had been placed in a golden prison","She had been transformed into a flower"],a:1,vs:"रावणवधे तव बाणः ब्रह्मास्त्रेण समाप्तिमगात्।",exp:"Hanuman found Sita in the Ashoka grove, thin and sorrowful, sitting under a Simshupa tree surrounded by Ravana's demoness guards. Despite her plight, she was absorbed in thoughts of Rama.",fact:"Hanuman's crossing of the ocean, his search of Lanka, and his conversation with Sita — called the Sundara Kanda — is considered the most auspicious section of the Ramayana. Reciting it is said to remove all obstacles."},
{n:34,t:"Ambarisha and Hamsa Guhya",kv:"34.6",vt:"ambarīṣa — King Ambarisha stood unmoved while Durvasa's fire demon charged at him. Your Sudarshana chakra alone protected him, chasing the angry sage across all worlds until Durvasa bowed at Ambarisha's feet.",q:"Why was the Sudarshana chakra sent after the great sage Durvasa?",o:["Because Durvasa insulted Vishnu","Because Durvasa created a demon to kill Ambarisha who was observing Vishnu's Ekadashi vrata — attacking a devotee is attacking the Lord","Because Durvasa stole temple offerings","Because Durvasa broke Brahma's rules"],a:1,vs:"अम्बरीषं रक्षयित्वा सुदर्शनं दुर्वाससं ताडितवान्।",exp:"King Ambarisha had observed the sacred Ekadashi vrata in Vishnu's honor. Durvasa arrived late and sent a fire-demon to kill Ambarisha. The Lord's Sudarshana automatically moved to protect His devotee.",fact:"Sudarshana chased Durvasa across all 14 worlds. Only when Durvasa prostrated at Ambarisha's feet and the devotee forgave him did the chakra relent — showing a devotee's forgiveness is more powerful than a sage's wrath."},
{n:35,t:"Ikshvaku Lineage",kv:"35.3",vt:"ikṣvāku vaṃśa — From the solar dynasty arose Ikshvaku, and from his lineage came the great kings who upheld Dharma. Every great avatara was born in a noble lineage.",q:"What is the significance of the solar dynasty in Narayaneeyam?",o:["It produced the greatest warriors","It is the lineage from which Rama was born, showing the Lord chooses pure vessels for His avataras","It ruled for the longest period","It built the most temples"],a:1,vs:"इक्ष्वाकुवंशे जाताना- मवतारस्तव शोभनः।",exp:"The solar dynasty maintained dharma across generations, culminating in the birth of Rama. The purity maintained across countless generations created the worthy vessel for the Lord's descent.",fact:"The Ikshvaku lineage includes 60,000+ kings before Sagara. The Bhagavata describes this dynasty to show that divine incarnations are the fruit of generations of dharmic living."},
{n:36,t:"Rama — Uttara Kanda",kv:"36.5",vt:"rāma nāma — The name of Rama is the greatest of all mantras. Even Shiva whispers it at the ear of the dying in Kashi. What more proof is needed?",q:"What does tradition say Lord Shiva whispers to the dying in Kashi?",o:["The Gayatri Mantra","The Rama Nama (Taraka Mantra)","The Vishnu Sahasranama","The Mahamrityunjaya Mantra"],a:1,vs:"रामनाम परं ब्रह्म शिवः काश्यां जपत्यजस्रम्।",exp:"Tradition holds that Shiva Himself whispers the Rama Nama (called Taraka Mantra) into the ears of all those who die in Kashi. This is why dying in Kashi is considered the highest liberation.",fact:"This beautiful tradition — Shiva as the greatest devotee of Rama — shows the unity of Shaiva and Vaishnava traditions. Shiva says Rama Nama is my food."},
{n:37,t:"Krishna Avatara — Birth",kv:"37.6",vt:"jāta kṛṣṇaḥ — At the auspicious midnight, in the prison of Kamsa, You were born. Chains fell, guards slept, doors opened. Vasudeva carried You across the Yamuna as she parted in reverence.",q:"How did Vasudeva carry the newborn Krishna across the flooded Yamuna?",o:["In a boat provided by a fisherman","On his head in a basket while the Yamuna parted and Adishesha spread his hood as an umbrella","By swimming across","The river miraculously dried up"],a:1,vs:"जातः कृष्णो मध्यरात्रौ कंसभीत्या वसुदेवः प्रापयत्।",exp:"Vasudeva balanced the newborn Krishna on his head in a wicker basket. The Yamuna, though flooded and stormy, parted to give way. The divine serpent Adishesha spread his thousand hoods over the baby as an umbrella.",fact:"The birth of Krishna happened at midnight on Ashtami of the dark fortnight of Bhadrapada — celebrated as Janmashtami. The midnight timing, the darkness, the storm — all were perfect for the Lord's secret arrival."},
{n:38,t:"Krishna Lila — Putana",kv:"38.5",vt:"pūtanā mokṣa — Even Putana, who came to kill You with poison, received liberation by Your touch. Those who approach You with evil intent are freed. What then of those who come with love?",q:"What liberation did Putana receive despite coming to kill Krishna?",o:["She became a demoness in heaven","She attained the status of a mother in Vaikuntha — Krishna suckled her breast and accepted the relationship of mother","She was reborn as a pious woman","She became a river"],a:1,vs:"पूतनामोक्षणं दत्त्वा त्वं स्तन्यं पीतवान् प्रभो।",exp:"Though Putana came to kill Krishna with poison on her breast, Krishna suckled her and drew out her very life-force. Because He accepted the nursing relationship, she received the status of a mother in the afterlife.",fact:"The Bhagavata comments: How much more blessed are the Gopis who fed Krishna real milk with pure love? Putana's liberation sets the bar — if even a murderous demoness was liberated, the devotees who loved Him truly were beyond measure."},
{n:39,t:"Trinavarta and Shakatasura",kv:"39.4",vt:"tṛṇāvarta — The demon Trinavarta caught baby Krishna and soared into the sky. But You became unbearably heavy and crushed him to earth. Even in infancy, You are the Lord of all.",q:"How did the demon Trinavarta attempt to kill baby Krishna?",o:["He disguised himself as a toy","He came as a whirlwind and lifted baby Krishna, but Krishna became so heavy He crushed the demon to earth","He poisoned the milk","He set fire to the cradle"],a:1,vs:"तृणावर्तं व्योमयानं गृहीत्वा भूमौ पातितवान्।",exp:"Trinavarta disguised himself as a whirlwind and caught baby Krishna, soaring into the sky. But Krishna expanded and became so heavy — heavier than the entire universe — that the demon was crushed to earth.",fact:"These early lilas of baby Krishna establish a theme: apparent helplessness concealing infinite power. The Lord plays the role of a baby perfectly, revealing His nature only in moments of necessity."},
{n:40,t:"Namakarana",kv:"40.5",vt:"nāmakaraṇa — When Garga Muni named You, he whispered privately that this child had appeared in other ages. Those who know His nature will cross all obstacles. Nanda rejoiced, not knowing his son was God.",q:"Why did Garga Muni perform Krishna's naming ceremony in secret?",o:["Because it was a night ceremony","To prevent Kamsa from learning about the child's divine identity","Because Nanda had not paid the appropriate dakshina","Because Yashoda was unwell"],a:1,vs:"नामकरणे गार्ग्यमुनिः कृष्णेति नाम दत्तवान्।",exp:"Vasudeva had privately arranged for Garga Muni to perform the naming ceremony secretly so that Kamsa's spies would not report a special ceremony that might alert the king about this divine child.",fact:"Garga Muni named the dark boy Krishna (dark one) and the fair boy Rama (pleasing one). He also whispered to Nanda that this child would bring joy and overcome all obstacles — one of the greatest understatements in scripture."},
{n:41,t:"Bala Lilas — Damodara",kv:"41.7",vt:"damodara — She tied rope after rope, each always two fingers too short. It was not the rope that held You, O Damodara. It was her love. You surrendered to a mother's devotion.",q:"When Yashoda tied Krishna to a mortar, what miracle followed?",o:["The mortar floated in the air","Krishna crawled between two arjuna trees dragging the mortar, and the trees (cursed gandharvas) were uprooted and liberated","Flowers rained from the sky","The rope turned to gold"],a:1,vs:"दामोदर दयासिन्धो मातृबद्धोऽसि रज्जुभिः।",exp:"Tied to a heavy mortar, baby Krishna crawled between two massive Arjuna trees. The mortar got stuck and Krishna pulled with such force that both trees were uprooted — releasing Nalakubara and Manigriva, two celestials cursed to be trees.",fact:"The name Damodara (one whose belly is bound by a rope) comes from this incident. It shows that the infinite Lord was bound by finite love. The month of Kartik is celebrated as Damodara month."},
{n:42,t:"Yashoda sees the Universe",kv:"42.6",vt:"mukhe jagat — In that small mouth — the universe entire. The fourteen worlds, mountains, oceans, stars, time itself — all in the mouth of this butter-thief. Yashoda shook with wonder, then forgot — for You restored her motherly love.",q:"Why did Yashoda initially look inside baby Krishna's mouth?",o:["To check if he had swallowed poison","Because she suspected he had eaten dirt and wanted to check","To see his divine teeth","Because a sage told her to"],a:1,vs:"मुखे जगत् पश्यन्ती यशोदा मोहिता तव मायया।",exp:"When friends told Yashoda that baby Krishna had eaten dirt, she checked his mouth. Instead of dirt, she saw the entire universe — all 14 worlds, the stars, time, space, herself, everything. Then He restored her Maya — her identity as His mother.",fact:"This lila has profound philosophical meaning: the Lord who contains the universe acts the part of a small child eating dirt. Maya is His instrument — He wields it to play the role of a son for Yashoda's joy."},
{n:43,t:"Vatsasura and Bakasura",kv:"43.3",vt:"vatsa bakāsura — When the calf-demon charged, You seized it and hurled it into a tree. When the heron-demon swallowed You, You expanded with heat until he spat You out — then split his beak apart.",q:"How did Krishna kill the demon Bakasura?",o:["By cutting his way out with a blade of grass","By expanding inside Bakasura's throat with intense heat until he spat Krishna out, then splitting his beak apart","By calling Balarama for help","By using the Sudarshana chakra"],a:1,vs:"वत्सबकासुरौ हत्वा बालकृष्णः सखीन् रक्षत्।",exp:"Bakasura (the heron demon) swallowed the young Krishna whole. Inside his throat, Krishna expanded with such intense heat that Bakasura was forced to spit Him out. Krishna then split Bakasura's beak with His bare hands.",fact:"The cowherd boys who witnessed these miraculous killings simply marveled for a moment and then continued playing — so naturally divine was Krishna's presence that miracles seemed normal."},
{n:44,t:"Aghasura Vadha",kv:"44.5",vt:"agha vadha — When all the boys walked into the python's mouth, You entered last, expanded within his throat — the demon burst, and the boys' souls rose like lights to freedom.",q:"What was the relationship between Aghasura, Putana, and Bakasura?",o:["They were all demons sent by different kings","Aghasura was the younger brother of Putana and Bakasura, all three sent by Kamsa to kill Krishna","They were unrelated demons","They were manifestations of the same demon"],a:1,vs:"अघासुरं वधित्वा त्वं सर्वान् बालान् समुद्धरः।",exp:"Aghasura was the younger brother of Putana (the poisonous nursemaid) and Bakasura (the heron demon). Kamsa had sent all three to kill the child Krishna. All three were slain and all three attained liberation.",fact:"When Aghasura died, his soul exited through the top of his skull (brahmarandhra) and merged into Krishna — witnessed by all celestials. This is described as the highest form of liberation (sayujya mukti)."},
{n:45,t:"Brahma Vimohana",kv:"45.7",vt:"brahma moha — You became each boy, each calf — identical in form, voice, and love — for an entire year. When Brahma returned and saw, he fell prostrate, his four heads touching the earth, his pride dissolved.",q:"What was Brahma trying to test and what did he discover?",o:["He was testing the limits of Maya","He was testing whether Krishna was truly Vishnu — and discovered that Krishna is the supreme reality beyond even Brahma's comprehension","He was angry at Krishna","He wanted the boys for himself"],a:1,vs:"ब्रह्मा मोहितो देव त्वद्भक्त्या स्वं विसर्जितः।",exp:"Brahma stole the boys and calves to test Krishna's divinity. Krishna multiplied Himself as perfect replicas of all the boys and calves for a year. When Brahma returned, he saw each boy was a four-armed Vishnu — his four heads touched the ground in surrender.",fact:"This lila is called Brahma Vimohana — the bewilderment of Brahma, the creator. If the creator himself is bewildered by Krishna's nature, what can be said of others?"},
{n:46,t:"Dhenukasura and Kaliya Prep",kv:"46.3",vt:"dhenukāsura — Dhenukasura, the great donkey demon who guarded the Tala forest, charged at Balarama. He caught him by the hind legs, whirled him and flung him — liberating the demon with His divine touch.",q:"Why was the Yamuna near Vrindavan poisonous before Kaliya was driven away?",o:["Because of pollution from nearby kingdoms","Because the great serpent Kaliya had settled there, his powerful venom making the water lethal to all","Because Kamsa had poisoned it","Because of a sage's curse"],a:1,vs:"धेनुकासुरं बलेन बलरामेण हतः सः।",exp:"The many-hooded serpent Kaliya had taken up residence in a deep pool of the Yamuna. His venom was so potent that the water became deadly — birds flying over fell dead, and any creature drinking from that stretch died instantly.",fact:"Kaliya had originally lived in the ocean but fled to the Yamuna because Garuda had been given a boon that he could not enter that particular pool — so it was Kaliya's refuge."},
{n:47,t:"Kaliya Mardana",kv:"47.8",vt:"kāliya mardana — Dancing on the thousand hoods of Kaliya, You pressed him down until blood flowed. When his wives prayed, Your compassion arose. You spared him and sent him to the ocean — protected by Your footprint.",q:"Who prayed for Kaliya's life, and what was the result?",o:["Kaliya's mother","Kaliya's wives (nagins) prayed with folded hands, and Krishna spared Kaliya, sending him to the Ramanaka island in the ocean","Narada intervened","Kaliya himself prayed"],a:1,vs:"कालियं मर्दयन् कृष्णः नृत्यन् तस्य फणोपरि।",exp:"When Kaliya was severely subdued by Krishna's dancing, his wives approached with folded hands and praised Krishna with beautiful prayers. Moved by their devotion, Krishna stopped and commanded Kaliya to leave the Yamuna and go to the Ramanaka Dvipa island.",fact:"Krishna left His footprint on Kaliya's hood as a mark. Since Garuda would not approach a being marked by his Lord's foot, this footprint became Kaliya's ultimate protection — the Lord's grace protecting even a defeated enemy."},
{n:48,t:"Pralambasura and Forest Fire",kv:"48.5",vt:"dāvānala — When the terrible forest fire encircled the cowherds, they closed their eyes in surrender. In an instant the fire was gone — You had swallowed it entirely. They opened their eyes to find You smiling.",q:"How did Balarama kill the demon Pralambasura?",o:["With his plough weapon","Pralambasura was carrying Balarama on his back in a game; Balarama recognized him and struck him with a blow so powerful his head split","By calling Krishna for help","By throwing him into the fire"],a:1,vs:"दावानलं पीत्वा कृष्णः व्रजं रक्षितवान् प्रभुः।",exp:"In a game where boys carried each other, Pralambasura chose to carry Balarama, intending to abduct him. When the demon flew up, Balarama recognized him and struck him with his fist so powerfully that Pralambasura's head split.",fact:"The forest fire swallowed by Krishna in this Dasakam prefigures the end of the world — when the cosmic fire will consume everything. Krishna showed the cowherds this truth briefly, then restored the normal world with a smile."},
{n:49,t:"Govardhan Leela",kv:"49.7",vt:"govardhana dhārī — You lifted the mountain as a child holds an umbrella, on the tip of Your little finger, for seven days. Indra's rains spent themselves uselessly, and the lord of heaven bowed his head in shame.",q:"What was Krishna's argument to convince the Vraja people to worship Govardhan instead of Indra?",o:["That Govardhan was more powerful than Indra","That the mountain directly sustained them — giving shelter, grass for cows, fruit — whereas Indra gives rain as his cosmic duty requiring no special worship","That Indra had become arrogant","That Govardhan was Vishnu's avatar"],a:1,vs:"गोवर्धनं धृत्वाङ्गुल्या व्रजं रक्षित्वा इन्द्रं जितः।",exp:"Krishna argued that Govardhan directly sustained the Vraja people with shade, grass, fruit, and shelter. Indra gives rain as his cosmic duty, like a government servant doing his job. One's immediate sustainer deserves direct gratitude.",fact:"Govardhan hill is itself considered a form of Krishna. Devotees today still do the Govardhan Parikrama on Annakoot day, one day after Diwali, recreating the worship that Krishna instituted."},
{n:50,t:"Indra's Apology and Govinda",kv:"50.5",vt:"govinda nāma — When Indra bathed You with the celestial Ganga and Surabhi showered her milk, You received the name Govinda — protector of cows, earth, and the Vedas — from the king of heaven himself.",q:"Who gave Krishna the name Govinda and what does it mean?",o:["Lord of Gopis — given by the Gopis","Protector of cows, earth, and Vedas — given by Indra himself who came to apologize","The dark one — given by Garga Muni","Butter-thief — given by the Gopis mothers"],a:1,vs:"गोविन्दनाम देवेन्द्रो सुरभ्या दत्तमभिषेकः।",exp:"A humbled Indra came down with the divine cow Surabhi and Airavata. He bathed Krishna with the waters of the celestial Ganga and named Him Govinda — protector of the Vedas, earth, and cows.",fact:"Three meanings of Go converge in the name Govinda: cow, earth, and Vedic speech. This name given by Indra after his defeat is one of the most beautiful moments of divine surrender in the Bhagavata."},
];

const D2 = [
{n:51,t:"Rasa Leela Prelude",kv:"51.6",vt:"veṇu nāda — When the flute sang in the autumn moonlight, the Gopis forgot everything. They ran through the dark forest toward that sound. Even the trees leaned toward You, and the deer stood still, ears raised, listening.",q:"When Krishna tested the Gopis by asking them to return home, what reason did He give?",o:["That the forest was dangerous at night","That a woman's duty is to serve her husband and family — the highest service to Krishna was to return home and fulfill those duties faithfully","That only married women could attend","That the dance had not yet begun"],a:1,vs:"वेणुनादं श्रुत्वा गोप्यः सर्वं त्यक्त्वा त्वामागताः।",exp:"Krishna told the Gopis that their dharma as wives and daughters was to return home. This was a test of their supreme love. The Gopis replied that He alone was their true husband — that all dharmas find fulfillment in surrender to Him.",fact:"The Gopi Gita and this prelude establish the Gopis as the highest example of Bhakti in the entire Bhagavata. Their love was so total that even dharma arguments could not move them."},
{n:52,t:"Rasa Leela",kv:"52.8",vt:"rāsa maṇḍala — In that moonlit circle, You stood between each Gopi as if there were only one pair. Each Gopi felt You were hers alone. The celestials rained flowers — for nowhere in three worlds was there love like this.",q:"How did Krishna multiply Himself during the Rasa dance?",o:["He used a mirror trick","He appeared between each pair of Gopis simultaneously — each Gopi experienced Krishna dancing only with her","He sent illusions of himself","Balarama helped play some roles"],a:1,vs:"रासमण्डलमध्ये कृष्णः प्रतिगोप्यं व्यवस्थितः।",exp:"Krishna multiplied Himself so that He appeared between each Gopi simultaneously. Thousands of Gopis, thousands of Krishnas — each pair dancing as if alone. This is called Rasa-mandala — the divine circle dance where the one becomes many.",fact:"The Rasa Leela has a profound spiritual meaning: each soul feels an exclusive relationship with God, while God is equally present with all souls simultaneously. The Lord's love is both universal and intimate at once."},
{n:53,t:"Gopi Gita",kv:"53.5",vt:"gopi gīta — O Krishna, we do not ask for heaven or liberation. We ask only that the lotus feet we have placed in our hearts never be removed. This is the Gopi Gita — the highest prayer.",q:"Why did Krishna disappear from the Rasa Leela, and what did the Gopis do?",o:["He was called away by Kamsa's messengers","To test and deepen their love — remove the pride that arose in some Gopis. The Gopis searched the forest in anguish, enacting His lilas, singing the Gopi Gita","He went to sleep","Balarama called Him away"],a:1,vs:"गोपीगीतं परमभक्तेः निदर्शनं विश्वोत्तमम्।",exp:"When some Gopis grew slightly proud of being chosen by the Lord, Krishna disappeared. The Gopis searched the forest in desperate anguish, enacting His lilas, asking the trees and rivers where He had gone. Their lament became the Gopi Gita.",fact:"The Gopi Gita has 19 verses and is considered the heart of the 10th Skandha of the Bhagavata. Commentators say these verses are more philosophically dense than even the Gita — expressed in the language of love rather than reason."},
{n:54,t:"Rukmini Haran",kv:"54.4",vt:"rukmiṇī haraṇa — Rukmini's letter reached You in Dwaraka: I am Yours from birth. If You do not come, I will give up my life. And You came — alone, in a single chariot — and carried her away.",q:"How did Rukmini communicate her love and desire for Krishna to elope?",o:["Through her childhood friend","Through a brahmin messenger who carried her letter to Krishna, describing her love and warning she was to be married to Shishupala","Through a dream she sent","Through Narada Muni"],a:1,vs:"रुक्मिणीहरणं कृत्वा कृष्णः प्राप्य पत्नीमगात्।",exp:"Rukmini sent a brahmin messenger to Dwaraka carrying her letter to Krishna. The letter expressed her undying love, explained she was being given to Shishupala, and asked Krishna to come and abduct her on her way to the temple.",fact:"Rukmini's letter is one of the great love letters of world literature. She addresses Krishna as the supremely qualified being and then says simply: I am Yours. Come. This is both a love letter and a philosophical statement of the soul's longing for God."},
{n:55,t:"Syamantaka Mani",kv:"55.6",vt:"jāmbavatī — After 28 days of battle in the dark cave, Jambavan recognized You as Rama, his beloved Lord. He surrendered with tears, offered his daughter Jambavati and the gem — and You who had been Rama now embraced him as Krishna.",q:"Why was Krishna falsely accused in the Syamantaka jewel incident?",o:["Because he was seen near the gem","Because Satrajit's brother Prasena was killed by a lion while wearing the gem; people assumed Krishna had killed Prasena for the gem","Because a demon framed him","Because Kamsa spread rumors"],a:1,vs:"जाम्बवती-सत्यभामे स्यमन्तकेन लब्धे।",exp:"Satrajit's brother Prasena wore the Syamantaka gem and went hunting, where a lion killed him and took the gem. The lion was then killed by Jambavan who took the gem. When Prasena disappeared, people whispered that Krishna had coveted it.",fact:"This incident shows Krishna voluntarily clearing His name — He could have ignored the accusation, but went into the forest to find the truth. His personal integrity and respect for public trust made Him trace the gem all the way to Jambavan's cave."},
{n:56,t:"Narakasura Vadha",kv:"56.7",vt:"naraka vadha — From Narakasura's citadel You freed 16,000 women — accepting them all as queens, giving each her dignity, each her palace, and Your presence in each home simultaneously.",q:"What auspicious festival originated from Krishna's victory over Narakasura?",o:["Holi","Diwali (specifically Naraka Chaturdashi) — people lit lamps to celebrate his defeat and the liberation of the imprisoned women","Janmashtami","Navratri"],a:1,vs:"नरकासुरं हत्वा षोडशसहस्रयोषिताः मुक्ताः।",exp:"The defeat of Narakasura and the liberation of the 16,100 imprisoned women is celebrated as Naraka Chaturdashi, the day before Diwali. People wake before dawn and light lamps to celebrate the victory of light over darkness.",fact:"Narakasura had stolen Aditi's divine earrings and imprisoned 16,000 daughters of gods and kings. Krishna and Satyabhama together attacked Pragjyotisha on Garuda — she drove the chariot — and destroyed the demon."},
{n:57,t:"Marriages and Dwaraka",kv:"57.5",vt:"dvarakā — Narada visited each of the 16,108 palaces. In each one he found You fully present — not distracted, not hurrying. He fell at Your feet and wept: I have never seen love like this.",q:"What did Narada find when he visited all of Krishna's palaces in Dwaraka?",o:["Krishna was only in a few palaces","In every single palace he found Krishna fully present, each queen experiencing His complete attention","Krishna appeared briefly when Narada arrived","Narada gave up after a few palaces"],a:1,vs:"द्वारकायां कृष्णः सर्वैः पत्नीभिः सह विराजते।",exp:"Narada personally visited all 16,108 palaces in Dwaraka. In every single one, he found Krishna fully present — not distracted — each queen experiencing an exclusive, full relationship. Narada fell at Krishna's feet overwhelmed.",fact:"This miracle is the Dwaraka Lila's central teaching: God is one, yet fully present for each devotee individually. The devotee who feels Krishna is mine is not wrong — the Lord's capacity for intimate, exclusive relationship with each soul is infinite."},
{n:58,t:"Shishupaala Vadha",kv:"58.6",vt:"śiśupāla vadha — You bore a hundred insults patiently. On the 101st, the Sudarshana flew. In death, Shishupala's soul rose as a radiant light and merged into You.",q:"Why did Krishna tolerate 100 insults from Shishupala before acting?",o:["Because Shishupala was a king","Because Krishna had promised Shishupala's mother (his own aunt) that He would forgive her son 100 times","Because Yudhishthira asked Him to be patient","Because the Sudarshana needed time to charge"],a:1,vs:"शिशुपालवधे चक्रं शतापराधे प्रयुक्तम्।",exp:"Shishupala's mother (Krishna's aunt) had begged Krishna to forgive her son's offenses when she first learned of the prophecy. Krishna promised to forgive 100 offenses and patiently counted each insult at the Rajasuya assembly.",fact:"Shishupala, who spent his life insulting Krishna, attained liberation by merging into Him at death — because constant thought of Krishna (even in hatred) purifies. The soul that always thinks of Krishna attains Him regardless of the emotion."},
{n:59,t:"Draupadi Vastraharan",kv:"59.6",vt:"draupadi rakṣaṇa — When Draupadi raised both hands to You in total surrender, abandoning the grip on her sari — in that moment of complete surrender, You began the endless cloth.",q:"What is the key spiritual teaching of the Draupadi Vastraharan episode?",o:["That husbands should protect their wives","That complete surrender (prapatti) — letting go of self-effort and calling only on God — brings infinite divine protection","That gambling is sinful","That the Kauravas were more powerful"],a:1,vs:"द्रौपद्याः वस्त्रहरणे कृष्णः रक्षां चकार सः।",exp:"As long as Draupadi held her sari with one hand and cried out to her husbands, no protection came. The moment she raised both hands in complete surrender to Krishna, the cloth became endless. God's protection is activated by total surrender.",fact:"Traditional commentary says Draupadi first held her sari and called Hey Govinda! When the cloth ran out, she finally raised both hands in full surrender — and the miraculous cloth began. Partial surrender gives partial protection."},
{n:60,t:"Kuchela (Sudama) Charitra",kv:"60.7",vt:"kucela dāna — Sudama came with a handful of beaten rice — too ashamed to offer it. But You snatched it and ate it with relish, declaring each handful gave You more joy than all the wealth of the universe.",q:"What did Sudama find when he returned home after visiting Krishna in Dwaraka?",o:["A letter from Krishna with money","His hut had been transformed into a magnificent palace and his family dressed in fine clothes — all by Krishna's grace without any explicit request","Nothing had changed","Krishna's servants had arrived with gifts"],a:1,vs:"कुचेलो दत्त्वा तण्डुलान् कृष्णेन सम्पद्भिः पूरितः।",exp:"Sudama had been too shy to mention his poverty to Krishna. Krishna, who knew everything, transformed Sudama's humble hut into a grand palace while they were together. Sudama returned to find an unrecognizable home.",fact:"The beauty of the story is that Krishna gave without being asked — pure grace. Sudama went to ask for help but could not bring himself to do it. This shows the Lord knows the devotee's need before they speak."},
{n:61,t:"Kurukshetra — Bhagavad Gita Context",kv:"61.4",vt:"sārathi — You who hold the universe chose to hold the reins of a chariot. Arjuna's charioteer — not the general, not the king, but the servant. The Lord makes Himself small for His devotee's sake.",q:"How did Krishna end up as Arjuna's charioteer in the Kurukshetra war?",o:["Because He was not a warrior","He offered each side a choice: His army or Himself unarmed. Duryodhana chose the army; Arjuna chose Krishna, who then became his charioteer","Because Arjuna forced him","Because Balarama fought for the Kauravas"],a:1,vs:"सारथिः कृष्णः पार्थस्य कुरुक्षेत्रे महायुधे।",exp:"Before the war, both Duryodhana and Arjuna came to Krishna for support. He offered a choice: His vast Narayani army or Himself alone but unarmed. Duryodhana chose the army; Arjuna chose Krishna. Krishna then took the role of charioteer.",fact:"The Lord's choice to hold the reins is a profound teaching on seva (service). The greatest being becomes the greatest servant of His devotee. This is why the Gita says the Lord is the servant of His devotee — not the other way around."},
{n:62,t:"Bhagavad Gita — Karma Yoga",kv:"62.6",vt:"karmaṇyevādhikāras te — You have a right to action alone, never to its fruits. Do not let the fruit be your motive, nor let there be any attachment to inaction.",q:"What was the core of Arjuna's despondency (Vishada) at the start of the Gita?",o:["Arjuna feared losing the war","Arjuna broke down seeing his relatives on the opposing side and refused to fight. Krishna's first teaching: the Self is immortal, grief over killing bodies is mistaken","Arjuna was angry at Duryodhana","Arjuna doubted his own skill"],a:1,vs:"कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।",exp:"Arjuna, seeing grandfathers, uncles, and teachers on the Kaurava side, was overwhelmed with grief and refused to fight. Krishna's opening teaching was: The wise grieve neither for the living nor the dead. The Self is eternal and cannot be killed.",fact:"The Bhagavad Gita begins with the word Dharma (Dharmakshetre) and ends with the word Me (mama). The entire Gita is thus framed as Dharma culminating in surrender to Me — a complete spiritual vision in one scripture."},
{n:63,t:"Bhagavad Gita — Vishwarupa",kv:"63.7",vt:"viśvarūpa — At Arjuna's prayer You revealed the Vishwarupa — a million suns blazing at once. Arjuna trembled and begged: Show me again that gentle, four-armed form — that form I know as Krishna.",q:"What special gift did Krishna give Arjuna to be able to see the Vishwarupa?",o:["A divine mirror","Divya Chakshu (divine eye) — human eyes cannot perceive the cosmic form","A special mantra","He purified Arjuna's heart completely"],a:1,vs:"विश्वरूपं दर्शयित्वा दिव्यचक्षुः अर्जुनाय दत्तम्।",exp:"Before revealing the Vishwarupa, Krishna granted Arjuna Divya Chakshu — divine sight. Human eyes are calibrated for the material world and cannot perceive the infinite cosmic form. Only with the Lord's gift of divine vision could Arjuna witness it.",fact:"The Vishwarupa chapter (Chapter 11) of the Gita is called the most magnificent vision in all world literature — a million suns arising simultaneously, all armies swallowed by blazing mouths, awe and terror and infinite beauty simultaneously."},
{n:64,t:"Bhagavad Gita — Surrender",kv:"64.8",vt:"sarva dharmān — Abandon all paths and surrender unto Me alone. I shall liberate you from all sins — do not grieve. This final promise of the Gita is the Lord's personal guarantee — spoken once to Arjuna, meant for every soul.",q:"What were Arjuna's last words to Krishna at the end of the Bhagavad Gita?",o:["I will fight as You command","Nashtho mohah smritir labdhaa — My delusion is destroyed, memory is regained. I stand with doubts removed. I will act according to Your word","I surrender everything to You","I am ready, let the battle begin"],a:1,vs:"सर्वधर्मान् परित्यज्य मामेकं शरणं व्रज।",exp:"Arjuna's final words: Nashtho mohah smritir labdhaa — My delusion is destroyed. I have regained my memory of who I truly am. Your grace has removed my doubts. I will do as You say. This is the ideal response to the Gita's teaching.",fact:"The Gita ends with Sanjaya's words: Wherever is Krishna and wherever is Arjuna — there will be prosperity, victory, happiness, and firm policy. The Gita is a promise about every situation where the Lord and the devoted soul are together."},
{n:65,t:"Ashwatthama and Parikshit",kv:"65.5",vt:"parikṣit rakṣā — When Ashwatthama's brahmastra targeted the unborn Parikshit, You entered that dark space as the tiniest of forms and shielded him with Your Sudarshana, so the Bhagavata lineage would survive.",q:"What punishment did Ashwatthama receive for using the Brahmastra against an unborn child?",o:["He was killed by Arjuna","He was stripped of his forehead gem and cursed to roam the earth in misery for 3000 years without human contact","He was imprisoned in Dwaraka","He was forgiven by Krishna"],a:1,vs:"परीक्षितं गर्भगतं सुदर्शनेन रक्षितवान्।",exp:"Draupadi asked that Ashwatthama's life be spared. But Krishna decreed that a brahmin who attacked women and children deserved punishment: his forehead gem was removed, and he was cursed to wander alone for 3000 years.",fact:"Parikshit, protected by Krishna in the womb, was born with special markings indicating his divine protection. He grew up to be the great king whose story frames the entire Bhagavata Purana — the Bhagavata exists because Parikshit was kept alive."},
{n:66,t:"Bhishma's Teaching — Vishnu Sahasranama",kv:"66.6",vt:"viṣṇu sahasranāma — As Bhishma lay on his bed of arrows, You stood before him in silence. He who had lived by dharma named Your thousand names — each name a universe, each syllable a mantra.",q:"What special boon enabled Bhishma to lie on a bed of arrows for 58 days without dying?",o:["A boon from Brahma","His boon of Ichha Mrityu (death only by his own will), which he received from his father Shantanu for giving up his claim to the throne","A blessing from Vishnu","A mantra given by his guru"],a:1,vs:"विष्णुसहस्रनामानि भीष्मः शरशय्यागतः पठत्।",exp:"Bhishma had the boon of Ichha Mrityu — death only at his own choosing — given by King Shantanu as a reward for Bhishma's great sacrifice. When Arjuna's arrows felled him, he lay on the arrow-bed for 58 days waiting for the auspicious Uttarayana.",fact:"The Vishnu Sahasranama is embedded in the Mahabharata's Anushasana Parva, taught by Bhishma to Yudhishthira with Krishna as the silent witness. Krishna's presence as the subject of each name while Bhishma recited them is one of the most moving scenes in all literature."},
{n:67,t:"Parikshit and Shuka Muni",kv:"67.4",vt:"kim ekaṃ — King Parikshit asked: What is the one thing a man facing death should do? Shuka answered without hesitation: Hear the glories of Vishnu. And for seven days, the Bhagavata was narrated.",q:"Why was King Parikshit cursed to die within seven days?",o:["For killing a sage's son in battle","For placing a dead snake around the neck of meditating sage Shamika as a prank; Shamika's son Shringi cursed him in anger","For breaking a sacred vow","For disrespecting a brahmin at his court"],a:1,vs:"किमेकं दैवतं लोके परीक्षित् शुकं पप्रच्छ।",exp:"King Parikshit, while hunting, came to sage Shamika's hermitage thirsty. The sage was deep in meditation and did not respond. Parikshit, irritated, placed a dead snake around the sage's neck. The sage's son Shringi, furious, cursed Parikshit to die of snakebite within seven days.",fact:"Parikshit's first reaction on hearing the curse was not fear but gratitude — he saw it as the Lord's grace forcing him to make the best use of his remaining time. He sat on the banks of the Ganga, renouncing food and water, to hear the Bhagavata."},
{n:68,t:"Kansa Vadha",kv:"68.8",vt:"kaṃsa vadha — You leapt onto the throne and seized Kansa by the hair. As your uncle fell, You stood over him — not in rage but in compassion. Even Kansa, who had thought of You constantly in fear, attained liberation.",q:"In what form did Kansa attain liberation?",o:["Sayujya (merger into the Lord) — because he had constantly thought of Krishna out of fear, keeping the Lord's form always in his mind","He was reborn as a great devotee","He attained Brahmaloka","He became a star"],a:0,vs:"कंसं निहत्य बन्धनात् देवकीवसुदेवौ मुक्तौ।",exp:"Kansa attained Sayujya Mukti (merger into the Lord) because — despite being an enemy — he had thought of Krishna constantly since the divine voice prophesied his death. Constant remembrance of the Lord, even through fear, purifies and liberates.",fact:"The Bhagavata teaches Dvesha Bhakti — liberation through intense focus on the Lord even through enmity. Kansa, Shishupala, and Ravana all attained liberation because the Lord was always in their minds."},
{n:69,t:"Sandipani Ashram",kv:"69.5",vt:"guruvara dakṣiṇā — You learned all knowledge in 64 days and as guru dakshina retrieved Sandipani's dead son from Yama. From the conch Panchajanya you blew the first divine note.",q:"How did Krishna's famous conch Panchajanya come into His possession?",o:["It was a gift from Indra","It was retrieved from the ocean demon Shankhasura who had swallowed Sandipani's son","It was made by Vishwakarma","It was Arjuna's conch"],a:1,vs:"गुरुवर-दक्षिणार्थं शङ्खासुरं हत्वा शिष्यं आनीतवान्।",exp:"The ocean demon Shankhasura had swallowed Sandipani's son. Krishna dove into the ocean, slew Shankhasura, and recovered both the boy and the demon's conch shell. This became Krishna's famous Panchajanya — blown at Kurukshetra.",fact:"Sandipani Muni's ashram is in Ujjain (modern Madhya Pradesh), still maintained as a pilgrimage site. Krishna and Balarama were said to be ideal students — completing their education in a supernaturally short time."},
{n:70,t:"Jarasandha and Dwaraka",kv:"70.4",vt:"dvārakā nirmāṇa — Rather than see Mathura destroyed, You built Dwaraka overnight — a golden island city in the western sea, planned by Vishwakarma. Retreat is not defeat when the Lord plans the next move.",q:"Why did Krishna strategically retreat from Jarasandha and build Dwaraka?",o:["Because Jarasandha was too powerful","To protect the citizens of Mathura from repeated destruction; the battle would continue on Krishna's terms, not Jarasandha's","To fulfill a prophecy","Because Balarama asked Him to"],a:1,vs:"द्वारकानिर्माणं कृत्वा जरासन्धाद् रक्षितवान्।",exp:"Jarasandha attacked Mathura 17 times. Each time Krishna could have won, but the destruction of the city and suffering of citizens made this costly. By moving to the island of Dwaraka, Krishna removed His people from harm and changed the strategic situation.",fact:"The construction of Dwaraka happened in a single night — Vishwakarma built it at Krishna's request. The city was planned with all facilities and was said to be a replica of Vaikuntha on earth. It is now believed to lie submerged off the coast of Gujarat."},
{n:71,t:"Dwaraka — the golden city",kv:"71.3",vt:"dvārakā varṇana — Dwaraka shone like a second Vaikuntha on earth. Its streets were paved with gems, its towers touched the clouds, its citizens knew no sorrow. And at its center, You lived as a householder — a model for all.",q:"What happened to the city of Dwaraka after Krishna departed from earth?",o:["It was conquered by enemies","The ocean swallowed Dwaraka as per Krishna's instruction, ensuring no trace would remain to distract people","It was renamed and continues today","It was transported to Vaikuntha"],a:1,vs:"द्वारका वैकुण्ठसमा समुद्रे निर्मिता कृष्णेन।",exp:"After Krishna departed from earth, the ocean swallowed Dwaraka as He had instructed. The city, built by Vishwakarma, was submerged to prevent it from becoming corrupted after the Lord's departure.",fact:"Archaeological discoveries off the coast of Dwarka in Gujarat — submerged structures, ancient anchors, and pottery — have been cited as possible evidence of this legendary city, generating considerable scholarly and spiritual interest."},
{n:72,t:"The eight queens",kv:"72.5",vt:"aṣṭa mahiṣī — Eight queens, each a goddess. Rukmini with reverence, Satyabhama with pride, Kalindi with purity. And You — the one undivided Lord — loved each completely, as the ocean fills each shore equally.",q:"Who are the Ashtamahishis (eight principal queens) of Krishna?",o:["Rukmini, Satyabhama, Jambavati, Kalindi, Mitravinda, Nagnajiti, Bhadra, Lakshmana","Rukmini, Satyabhama, Radha, Kalindi, Gopis, Devaki, Yashoda, Subhadra","Only Rukmini and Satyabhama are principal queens","All 16,108 queens are equal with no principal queens"],a:0,vs:"अष्टमहिषीभिः सह कृष्णः द्वारकायां विराजते।",exp:"The eight principal queens (Ashtamahishis) of Krishna are: Rukmini, Satyabhama, Jambavati, Kalindi, Mitravinda, Nagnajiti, Bhadra, and Lakshmana. Each represents a different quality of devotion and love.",fact:"Each of the eight queens represents a different quality of devotion — Rukmini represents jnana-bhakti, Satyabhama represents possessive love, Jambavati represents love born from long association — together presenting the full spectrum of loving relationships with God."},
{n:73,t:"Samba and the iron pestle curse",kv:"73.4",vt:"durvāsa tṛpti — When Durvasa demanded food at midnight, the Yadava women fed him until satisfied. Durvasa blessed them — for the Lord protects those who serve His devotees.",q:"How did the iron pestle curse on the Yadavas come about?",o:["Durvasa cursed them for disturbing his meditation","Young Yadavas mocked sages by dressing Samba as a pregnant woman; the enraged sages said he would deliver an iron pestle that would destroy the Yadavas","A curse from Gandhari after the Kurukshetra war","A curse from Ashwatthama"],a:1,vs:"दुर्वाससं तर्पयित्वा यादवाः आशीर्वादं प्राप्ताः।",exp:"Young Yadavas dressed Samba (Krishna's son) as a pregnant woman and brought him before visiting sages, asking them to predict the birth. The sages saw through the jest and cursed: he would deliver an iron pestle that would be the instrument of their destruction.",fact:"When the iron pestle was ground to powder and thrown into the sea, sharp reeds grew on the shore. It was these reeds that the Yadavas eventually used to kill each other at their final gathering at Prabhasa."},
{n:74,t:"Usha and Aniruddha",kv:"74.6",vt:"bāṇa yuddha — Shiva himself took up arms for his devotee Banasura, and You fought Your greatest devotee in single combat. You subdued Shiva with Your Jrimbhana astra — causing him to yawn helplessly — then freed him and pardoned Banasura.",q:"How did Usha first encounter Aniruddha before their actual meeting?",o:["Through a letter carried by Narada","Through a dream in which she saw a handsome young man; her friend Chitralekha drew portraits of divine and royal men until Usha identified Aniruddha","At a swayamvara","Through a vision given by Parvati"],a:1,vs:"बाणयुद्धे शिवो जितः कृष्णेन जृम्भणास्त्रेण।",exp:"Usha, daughter of Banasura, dreamed of a beautiful young man. She described him to her friend Chitralekha, an artist and yogini. Chitralekha drew portraits of all notable men until Usha excitedly identified Aniruddha — Krishna's grandson.",fact:"Chitralekha used her yogic power to travel through space to Dwaraka, find the sleeping Aniruddha, and teleport him to Usha's palace. He woke up in a beautiful chamber with Usha. When Banasura discovered them, the great battle began."},
{n:75,t:"Paundraka Vadha",kv:"75.3",vt:"pauṇḍraka vadha — Paundraka dressed as Krishna and demanded You give up Your divine symbols. You smiled and sent your actual Sudarshana spinning toward him. He died holding a fake Sudarshana while the real one ended his imposture.",q:"What was uniquely ridiculous about Paundraka's challenge to Krishna?",o:["He challenged Krishna to a wrestling match","He actually dressed up with fake conch, disc, and yellow garments imitating Krishna and declared himself the real Vasudeva, demanding Krishna give up his fake divine symbols","He claimed to have defeated Balarama","He sent an army of demons disguised as devotees"],a:1,vs:"पौण्ड्रकं सुदर्शनेन हत्वा कृष्णः विजयी।",exp:"Paundraka had convinced himself he was the true Vasudeva. He wore fake versions of Krishna's symbols — conch, discus, mace, lotus, yellow silk — and sent a messenger demanding that Krishna abandon his false symbols. Krishna responded by sending his real Sudarshana.",fact:"After Paundraka's death, his ally the King of Kashi sent a fire demon to attack Dwaraka. Krishna destroyed the demon with a glance from His toe — demonstrating that the Lord's smallest action contains infinite power."},
{n:76,t:"Vrikasura",kv:"76.5",vt:"vṛkāsura vadha — The demon chased Shiva to test his boon. You appeared as a young brahmin boy and with gentle logic convinced the demon to test the boon on his own head. One touch — and the demon was gone. Shiva embraced You in gratitude.",q:"How did Krishna save Shiva from Vrikasura's terrible boon?",o:["By fighting the demon directly","As a young brahmin student, He logically convinced the demon to test the boon on his own head — the demon did, and perished","By sending the Sudarshana chakra","By asking Brahma to revoke the boon"],a:1,vs:"वृकासुरं छलेन हत्वा शिवं रक्षित्वा कृष्णः स्मितः।",exp:"Vrikasura had received from Shiva the boon that whoever's head he touched would dissolve. He immediately tried to test it on Shiva. Krishna appeared as a young brahmin student and logically convinced the demon to test the boon on his own head.",fact:"This story teaches a profound lesson: boons obtained through ego are weapons that ultimately destroy their possessor. The Sudarshana chakra of discernment (wisdom) ultimately protects the devotee from all such weapons."},
{n:77,t:"Narada's amazement at Dwaraka",kv:"77.4",vt:"nārada vismaya — Narada flew from palace to palace and in each one found You fully present. He fell at Your feet and wept: In all my wanderings through the fourteen worlds, I have never seen love like this.",q:"What philosophical truth does Krishna's simultaneous presence in 16,108 palaces demonstrate?",o:["That Krishna was actually multiple beings","That God is both one and infinitely manifold — pure consciousness fully present everywhere simultaneously, not divided or diminished by multiplicity","That the other palaces had mirror projections","That time works differently in Dwaraka"],a:1,vs:"नारदो विस्मितोऽभूत् सर्वभवनेषु कृष्णं दृष्ट्वा।",exp:"Krishna's presence in all palaces simultaneously without division demonstrates the nature of pure consciousness: it is not limited by space like a physical body. God is whole and complete everywhere — giving complete attention to each devotee without the others being diminished.",fact:"Narada's amazement is the reaction of even the greatest devotee-sage when confronted with the full mystery of the Lord's nature. Even after ages of devotion and knowledge, the Lord's reality exceeds all comprehension."},
{n:78,t:"Balarama Lilas",kv:"78.5",vt:"balarāma roṣa — Balarama plunged His ploughshare into the earth of Hastinapura and began to drag it toward the Yamuna. The city shook, the Kauravas trembled, and finally they released Samba with folded hands.",q:"Why did Balarama go on a pilgrimage during the Kurukshetra war instead of fighting?",o:["He was too old to fight","Both the Pandavas and Kauravas were his relatives and students; unable to choose sides, he departed on pilgrimage along the Saraswati river","He was performing a penance","Krishna sent him away to protect him"],a:1,vs:"बलरामः हस्तिनापुरं हलेन आकर्षितुमुद्यतः।",exp:"Balarama had taught both Duryodhana and Bhima the mace. Both sides were his students and his relatives. Unable to fight for one against the other in good conscience, he chose the path of a renunciant — going on pilgrimage along the Saraswati.",fact:"Balarama's pilgrimage route along the now-invisible Saraswati river is detailed in the Mahabharata. He returned just as the war ended, in time to witness the mace duel between Bhima and Duryodhana — and was outraged by Bhima's blow below the belt."},
{n:79,t:"Kurukshetra — Balarama's role",kv:"79.4",vt:"balarāma tīrtha — Unable to choose between relatives and justice, Balarama went on pilgrimage. Even in absence, he shaped the war's outcome — for the world saw that the Lord's elder stands apart, devoted only to righteousness.",q:"Why was Balarama angry at the conclusion of the Bhima-Duryodhana mace duel?",o:["Because Bhima won","Because Bhima struck Duryodhana below the navel — a violation of mace combat rules; Balarama raised his ploughshare to punish Bhima before Krishna pacified him","Because the duel was unfair from the start","Because the Pandavas used weapons"],a:1,vs:"बलरामः तीर्थयात्रायां गते युद्धे नाभूत् कुरुक्षेत्रे।",exp:"In the final mace duel, Bhima could not match Duryodhana's skill. Krishna signaled to Bhima to strike Duryodhana below the navel — an illegal blow. Duryodhana fell. Balarama, who had taught Duryodhana, was enraged at this adharma.",fact:"Krishna pacified Balarama by reminding him that Duryodhana himself had broken countless rules of dharma throughout his life — that the means used to bring down a supreme adharmi must sometimes match the situation."},
{n:80,t:"Yadava Mausala",kv:"80.7",vt:"yādava kṣaya — The destruction of the Yadavas was Your will — like fire that burns the forest it lives in. You watched with equanimity, for this too was Your plan.",q:"How did the Yadava clan destroy itself at Prabhasa?",o:["In a war against invaders","Intoxicated with wine at a gathering, the Yadavas quarreled and killed each other with reeds growing from the iron pestle powder that had been thrown into the sea","They were cursed by Gandhari","They drowned in the ocean"],a:1,vs:"यादवक्षयः प्रभासे मूसलैः स्वयं कृतः।",exp:"At Prabhasa on the seashore, the Yadavas held a festival where they drank heavily. Old quarrels inflamed by drink turned violent. They found no weapons — but the iron pestle powder had turned into sharp reeds on the beach. They used these reeds to kill each other.",fact:"This event fulfills multiple prophecies — the sage's curse about the iron pestle, Gandhari's curse on Krishna for allowing the Kurukshetra deaths, and the Lord's own plan to end the Yadava dynasty before leaving earth. The instrument of destruction came from within."},
{n:81,t:"Krishna's Departure",kv:"81.6",vt:"kṛṣṇa gamana — The hunter Jara trembled when he saw the face of the one he had shot. But You smiled: You have done well. Go without fear. Then You rose in a brilliant form to Vaikuntha — the earth shook and the Dvapara Yuga ended.",q:"Who was the hunter Jara who inadvertently shot Krishna?",o:["A demon sent by Kamsa","An ordinary tribal hunter; tradition identifies Jara as the reincarnation of Vali (killed by Rama), now completing the karmic cycle","A Kaurava warrior","He was punished severely after this"],a:1,vs:"कृष्णगमनं जरावाणेन व्याधेन पादे विद्धः।",exp:"Jara was a simple tribal hunter. Seeing what appeared to be a deer's foot (Krishna's reddish foot sole as He sat in yoga), he shot an arrow. When he saw Krishna's face, he was horrified. But Krishna told him not to fear, that this was destined.",fact:"The tradition says Jara was Vali in his previous life — killed by Rama from behind a tree. Krishna's foot, now the target, completes the karmic cycle. Krishna accepted this as His part in the cosmic drama, demonstrating equanimity even at His own departure."},
{n:82,t:"Kalki Avatara",kv:"82.5",vt:"kalki avatāra — At the end of Kali Yuga, when dharma is completely lost, You will be born as Kalki — riding a white horse, sword blazing — to end this age and begin the eternal cycle anew.",q:"In which village and to whom will Kalki be born?",o:["In Vrindavan to a cowherd family","In Shambhala village to a brahmin named Vishnuyasha","In Kashi to a sannyasi","In Ayodhya to a royal family"],a:1,vs:"कल्क्यवतारः कलियुगान्ते शम्भलग्रामे भविष्यति।",exp:"The Bhagavata Purana prophecies that Kalki will be born in Shambhala village to a brahmin family. His father's name is Vishnuyasha. He will ride a white horse and wield a blazing sword to destroy the forces of darkness at the end of Kali Yuga.",fact:"Some traditions identify the mysterious Shambhala of the Bhagavata with the Shambhala of Tibetan Buddhist prophecy — a hidden kingdom that will emerge at the critical moment. Both traditions await a coming avatar of cosmic renewal."},
{n:83,t:"Buddha Avatara",kv:"83.4",vt:"buddha avatāra — You incarnated as the compassionate one to stop the slaughter of animals in the name of sacrifice. By teaching ahimsa and the middle path, You redirected thousands toward inner purity.",q:"Why does the Bhagavata Purana include Buddha as an avatara of Vishnu?",o:["Because Buddha worshipped Vishnu","Because Vishnu incarnated as Buddha to stop Vedic animal sacrifices that had become mechanically cruel and to teach compassion and non-violence","Because Buddha performed miracles like Vishnu","Because Buddhist texts say so"],a:1,vs:"बुद्धावतारः करुणामयः पशुहिंसां निवारयितुम्।",exp:"The Bhagavata's view is that when Vedic rituals became corrupt — performed mechanically for selfish ends with mass animal slaughter — Vishnu incarnated as Buddha to redirect people. By teaching ahimsa, He achieved what stern correction could not.",fact:"Dushyanth Sridhar's commentary notes that the Lord's avataras are always perfectly suited to the need of the age. Buddha's teaching of the middle path — avoiding both extreme asceticism and indulgence — is itself a form of the Lord's eternal dharma teaching."},
{n:84,t:"Dattatreya Avatara",kv:"84.5",vt:"dattātreya — You became Dattatreya — wandering freely with dog companions. From the spider You learned creation and withdrawal. From the ocean, containment. Twenty-four gurus in nature — You taught that the wise man sees a teacher in everything.",q:"How many natural gurus did Dattatreya identify?",o:["Nine gurus","Twenty-four gurus from nature — earth, water, fire, sky, moon, sun, pigeon, python, ocean, moth, bee, elephant, deer, fish, and more — each teaching a specific spiritual truth","Twelve gurus — one for each month","Five gurus — the five elements"],a:1,vs:"दत्तात्रेयः चतुर्विंशति- गुरुभ्यः ज्ञानमुपाजगाम।",exp:"Dattatreya described 24 natural gurus, each teaching a different wisdom: from the earth he learned patience and giving, from the water purity, from fire intensity and transformation, from the python non-effort in receiving what comes.",fact:"This teaching — that the entire natural world is a guru — is the foundation of ecological spirituality. The Avadhuta Gita attributed to Dattatreya is one of the most radical non-dual texts in the tradition."},
{n:85,t:"Vyasa Avatara",kv:"85.6",vt:"vyāsa avatāra — Though You had compiled all knowledge as Vyasa, You felt no satisfaction. Narada came and said: You have not yet sung of pure devotion. Then You wrote the Bhagavata — and at last Your heart was full.",q:"Why was Vyasa unsatisfied even after composing the four Vedas, 18 Puranas, and the Mahabharata?",o:["Because they were not popular enough","Because though profound in knowledge, none centered purely on devotion to Vishnu and the sweetness of His lilas — without Bhakti Rasa, knowledge alone does not fulfill","Because they were too difficult","Because they were not yet written down"],a:1,vs:"व्यासावतारः सर्वशास्त्रं संकलय्य भागवतं रचितवान्।",exp:"Narada found Vyasa in a state of inexplicable sadness despite his vast literary output. He told Vyasa: You have not described the pure sweetness of devotion to the Lord. The Bhagavata Purana alone can fulfill you.",fact:"The Bhagavata Purana is described as the ripe fruit of the tree of Vedic wisdom — full of the sweet juice of Bhakti. Shuka Muni, like a parrot, pecked this fruit and ripened it further in his narration to Parikshit."},
{n:86,t:"Hamsa Guhya Stotram",kv:"86.4",vt:"haṃsa guhya — As the swan separates milk from water, the wise soul separates the eternal Self from the temporary world. Brahma prayed this hymn in secret — for the deepest truths are whispered by grace to the prepared heart.",q:"What does the Hamsa (swan) symbolize in the Hamsa Guhya Stotram?",o:["The Lord's vehicle (vahana)","Discrimination (viveka) — the swan's legendary ability to separate milk from water symbolizes the wise soul's ability to discern the eternal Self from the transient world","The soul's speed in attaining liberation","Brahma's pure nature"],a:1,vs:"हंसगुह्यं ब्रह्मणा एकान्ते स्तुतं रहस्यम्।",exp:"The Hamsa (swan) is a symbol of viveka — spiritual discrimination. Just as the swan supposedly separates milk from water, the liberated soul separates the eternal Atman from the temporary world of appearances.",fact:"Brahma composed the Hamsa Guhya while alone before creation — it is called secret because it deals with the innermost nature of the Lord, beyond all description. Even Brahma's highest prayer ends in the acknowledgment that God transcends all words."},
{n:87,t:"Shruti Gita",kv:"87.5",vt:"śruti gīta — The Vedas said: We can only say what You are not. You are beyond our words. Only through Your own grace can You be known. We bow to You, our source and our silence.",q:"What is the paradox that the Shruti Gita highlights about knowing the Lord?",o:["That only scholars can know God","The very Vedas which are means of knowledge declare themselves inadequate — He can only be known through His own grace, not through intellectual study","That God is unknowable to anyone","That rituals are superior to knowledge"],a:1,vs:"श्रुतिगीतं वेदैः गीतं त्वन्महिमानमनुत्तमम्।",exp:"The Shruti Gita presents the ultimate paradox: the Vedas, humanity's highest source of spiritual knowledge, declare that the Lord is beyond even their description. They can say what He is not (neti neti), but cannot fully say what He is. Only His grace reveals Him.",fact:"The Shruti Gita in the Bhagavata (10th Skandha) is considered one of the most philosophically sophisticated hymns in the tradition — the Vedas themselves becoming devotees, praising the Lord who is their own source."},
{n:88,t:"Santana Gopalam",kv:"88.6",vt:"santāna gopāla — The brahmin's children had gone to Vaikuntha by the Lord's will. When You brought them back, the parents wept with joy. This is why Santana Gopalam is recited for the blessing of children.",q:"How were the brahmin's children who kept dying at birth actually found?",o:["They were reborn in another village","Krishna and Arjuna journeyed beyond the seven sheaths of the universe to Vaikuntha where they found the children happily with the Lord; Krishna brought them back as a gift","They were found in the ocean","A sage had hidden them"],a:1,vs:"सन्तानगोपालस्तोत्रेण ब्राह्मणपुत्रान् वैकुण्ठात् आनीतवान्।",exp:"A brahmin friend of the Pandavas kept losing newborn children. He blamed Arjuna. Krishna and Arjuna journeyed beyond the seven sheaths of the universe to Vaikuntha where they found the brahmin's children happily with the Lord. Krishna brought them back.",fact:"The Santana Gopalam stotra derives its power from this episode — Krishna as the protector of children (Go-pala, also meaning protector of life). The form of Santana Gopalam — Krishna as a child holding a baby — is specifically worshipped for the blessing of children."},
{n:89,t:"Syamantaka conclusion",kv:"89.4",vt:"syamantaka śuddhi — To clear Your name, You stood before the assembly and told the entire story. The jewel was displayed, Your honor restored. Even God demonstrates innocence for the sake of teaching.",q:"What final resolution restored Krishna's honor in the Syamantaka jewel story?",o:["The gem was destroyed","Satrajit publicly apologized, returned the gem, and offered his daughter Satyabhama in marriage; the gem eventually came to Akrura whose presence kept Dwaraka prosperous","Krishna kept the gem as compensation","The gem was sent to Vishnu's abode"],a:1,vs:"स्यमन्तकशुद्धिः सभायां कृष्णेन स्वयं विनिवेदिता।",exp:"After the full truth came out, Satrajit publicly confessed, returned the Syamantaka gem, and offered his daughter Satyabhama in marriage to Krishna as apology. The gem eventually came to Akrura, whose righteous possession maintained the prosperity of Dwaraka.",fact:"The Syamantaka story shows Krishna's respect for dharma and public trust. His persistent effort to clear His name — even though He could have ignored the accusation — is a teaching on the importance of honor and truth for a leader."},
{n:90,t:"Time, Death, and Liberation",kv:"90.5",vt:"kāla tattva — Death is not an end but a door, O Lord. The Self never dies — it changes its garment. Those who know this walk through the world unattached, their hearts already at Your feet.",q:"According to Dasakam 90, what is the most powerful antidote to the fear of death?",o:["Ritual performance","The knowledge that the Atman is eternal and birthless — and devotion to the Lord who is beyond time itself","Accumulating merit through charity","Living a good life"],a:1,vs:"काल-तत्त्वं बोधयन् कृष्णः मुमुक्षून् मुक्तिं ददाति।",exp:"The Bhagavata's consistent teaching is that the Self (Atman) is beyond birth and death. Understanding this truth — and anchoring it in devotion to the Lord who is the Self of all selves — transforms the experience of death from terror to liberation.",fact:"This Dasakam gathers several philosophical threads from the Bhagavata about time, death, and liberation. Bhattathiri was himself facing disease and the possibility of death when composing Narayaneeyam — making these teachings deeply personal."},
{n:91,t:"Muchukunda Moksha",kv:"91.5",vt:"mucukunda mokṣa — Waking from his long sleep, Muchukunda saw You standing in the cave — radiant, dark, smiling. He who had fought for the gods for ages now found the greatest treasure: the vision of Vishnu, face to face.",q:"What boon did Muchukunda receive from Indra, and how did it lead to his liberation?",o:["Immortality — which led to endless suffering","Undisturbed sleep — which led Krishna to lure Kalayavana into the cave; when Muchukunda woke and burned Kalayavana with his gaze, he found Krishna standing before him","Victory in all battles","Rulership of heaven"],a:1,vs:"मुचुकुन्दमोक्षणे कालयवनो भस्मीभूतः।",exp:"Muchukunda had fought for the gods for ages. Exhausted, he asked only for sleep. Indra granted undisturbed sleep, and whoever woke him would be burned. Krishna led the demon Kalayavana into the cave. Kalayavana woke Muchukunda — was burned — and Muchukunda saw Krishna.",fact:"Muchukunda's request for just sleep after ages of warfare is deeply human. He asked for the smallest thing — rest. But God arranged that this small request would lead to the greatest gift: liberation. The Lord hears the heart's deepest need beneath its stated words."},
{n:92,t:"Narayana Kavacham",kv:"92.4",vt:"nārāyaṇa kavaca — May Narayana protect my head; Kesava my forehead; Achyuta my eyes; Vishnu my ears. Thus armored in the names of the Lord, no weapon can touch — for the devotee who wears this armor is wrapped in God Himself.",q:"To whom was the Narayana Kavacham originally given?",o:["To Arjuna before the Kurukshetra war","To King Indra by Vishvaksena (Vishnu's general) as a protective prayer that the devas used in their battles against the asuras","To Prahlada for protection against Hiranyakashipu","To Brahma at the time of creation"],a:1,vs:"नारायणकवचं इन्द्राय विष्वक्सेनेन दत्तम्।",exp:"The Narayana Kavacham was given to King Indra by Vishvaksena, the commander of Vishnu's celestial army. It assigns different forms/names of the Lord as protectors of different body parts and life situations.",fact:"The Narayana Kavacham from the Bhagavata's sixth Skandha is one of the most recited protective prayers in the Vaishnava tradition. Its power lies not in any magical formula but in the total presence of the Lord in every aspect of the devotee's existence."},
{n:93,t:"Gopis Katyayani Vrata",kv:"93.6",vt:"vastra haraṇa — When You took their garments as they bathed, the Gopis stood embarrassed. But this was Your teaching: before God, there is no covering. The Gopi who stands with hands raised in surrender is the soul stripped of ego.",q:"What was the spiritual meaning of Krishna taking the Gopis' garments?",o:["It was a playful prank with no deeper meaning","It represented the Lord taking away the Gopis' ego-covering — one must stand before God completely naked of ego to receive His grace","It was punishment for bathing in the river","It was part of a ritual"],a:1,vs:"वस्त्रहरणेन गोपीनां अहंकारनाशनं कृतम्।",exp:"The commentators explain the garment-taking as a profound spiritual teaching. Clothes represent the covering of ego, pride, and I-consciousness. Before the Lord, the devotee must be completely without ego — naked of self-importance.",fact:"The Gopis had undertaken the Katyayani Vrata — early morning bath in winter for one month, praying for Krishna as husband. Krishna's test of their devotion through this episode was the final purification before the Rasa Leela."},
{n:94,t:"Akrura's Vision in the Yamuna",kv:"94.5",vt:"akrūra darśana — Akrura dove into the Yamuna and saw You reclining on Ananta in the cosmic waters. He burst to the surface, looked at the chariot, dove again. You were everywhere: above in the chariot, below in the water.",q:"What did Akrura see when he dove into the Yamuna on the way to Mathura with Krishna?",o:["A treasure at the river's bottom","He saw Vishnu reclining on the serpent Ananta in the cosmic waters — the same form that is Vishnu in Vaikuntha, now appearing in the Yamuna","He saw the future of Mathura","He saw Kamsa's fate"],a:1,vs:"अक्रूरदर्शनं यमुनायां विष्णुं दृष्ट्वा विस्मितोऽभूत्।",exp:"While bathing in the Yamuna, Akrura had a divine vision: he saw Vishnu reclining on Adishesha in the cosmic waters, surrounded by celestials. Amazed, he surfaced and looked at Krishna in the chariot — the same face. He dove again — the same vision.",fact:"Akrura's vision is called the Akrura Darshana and is one of the most beautiful visions of the Lord in the Bhagavata. It established for Akrura — and for the reader — that the young boy on the chariot and the cosmic Lord of Vaikuntha are identical."},
{n:95,t:"Vidura and Maitreya",kv:"95.4",vt:"vidura praśna — Vidura, cast out of Hastinapura, wandered the holy rivers and found Maitreya. His questions were pure: How does the Lord of all compassion allow suffering? And the sage's answer unfolds the entire mystery of creation.",q:"What key question did Vidura ask Maitreya?",o:["Why did the Kurukshetra war happen?","Why does God allow suffering — how can the compassionate Lord be the source of a world filled with pain and death?","What is the nature of the soul?","How can one attain Vaikuntha?"],a:1,vs:"विदुरः मैत्रेयं प्राप्य जगत्कारणं पप्रच्छ।",exp:"Vidura, a man of great dharma who had been humiliated and exiled, asked the question that every suffering person asks: How can the supremely compassionate Lord be the source of a universe filled with suffering? Maitreya's answer spans several chapters of the Bhagavata's third canto.",fact:"Vidura is one of the most compassionate figures in the Mahabharata — he tried to prevent the war, was rejected, and left. His meeting with Maitreya on the banks of the Ganga is a model of how adversity becomes the teacher when we turn toward the right guide."},
{n:96,t:"Shaunaka and Suta Goswami",kv:"96.3",vt:"naimiśāraṇya — In the forest of Naimisha, the sages asked Suta: In this dark age of Kali, what is the one practice that purifies the soul? And Suta answered: The constant hearing and singing of the glories of Vishnu.",q:"What was the specific question 88,000 sages at Naimisharanya asked Suta Goswami?",o:["What is the highest form of worship?","What is the supreme good for humanity especially in the Kali age where people have short lives and little intelligence — Suta answered: hearing and chanting the glories of Vishnu","How was the universe created?","Who is the greatest saint?"],a:1,vs:"नैमिषारण्ये शौनकादयः सूतं पप्रच्छुः कल्याणमार्गम्।",exp:"The sages asked: Given that Kali Yuga is characterized by short lives, weak bodies, confused minds, and spiritual lethargy — what is the one practice that gives the highest good to the most people most easily? Suta's answer: Shravana and Kirtana of the Lord's glories.",fact:"This question and answer is the very first exchange of the Bhagavata Purana — it sets the entire agenda of the scripture. The answer — hearing and chanting — is deliberately accessible to all: no special birth, no elaborate ritual, no extraordinary penance required."},
{n:97,t:"Kamsa Vadha — Full retelling",kv:"97.6",vt:"kaṃsa mukti — Kamsa thought of You every moment in fear — yet You counted those thoughts too. In the moment You seized him, his liberation was already assured. You had been in his mind for 20 years.",q:"What was the sequence of events at the wrestling arena that led to Kamsa's death?",o:["Krishna went directly to Kamsa's throne","Krishna and Balarama first killed the elephant Kuvalayapida, then defeated the wrestlers Chanura and Mushtika, then Krishna leapt onto the royal dais and seized Kamsa by the hair","Balarama killed Kamsa while Krishna wrestled","The Sudarshana chakra was used"],a:1,vs:"कंसवधे मल्लयुद्धे कृष्णः कुवलयापीडं हतवान्।",exp:"The sequence: (1) Kuvalayapida the elephant blocked the entrance — Krishna killed it. (2) The champion wrestlers Chanura (facing Krishna) and Mushtika (facing Balarama) were defeated. (3) Krishna then leapt onto Kamsa's elevated throne, seized him by the hair, and drove him to the arena floor.",fact:"When Kamsa fell and Krishna stood over him, the assembled crowd was silent with awe. Then Krishna's parents Devaki and Vasudeva — imprisoned for 20 years — were freed. Devaki tried to embrace them but stood still with awe, seeing their divine radiance."},
{n:98,t:"Narayana's Supreme Nature",kv:"98.5",vt:"brahma paramātma — The one Truth is called Brahman by those who seek liberation, Paramatma by those who seek through yoga, and Bhagavan by those who love. Guruvayurappan is all three — available to all three kinds of seekers.",q:"What are the three aspects of the Absolute described in the Bhagavata?",o:["Brahma, Vishnu, Shiva — three separate gods","Brahman (impersonal absolute), Paramatma (the indwelling witness), and Bhagavan (the personal Lord) — three descriptions of the one Reality approached through Jnana, Yoga, and Bhakti respectively","Past, present, and future aspects of the Lord","Creation, sustenance, and dissolution"],a:1,vs:"ब्रह्म परमात्मा भगवान् एकस्यैव त्रिधा वर्णनम्।",exp:"The Bhagavata's famous verse states that the one Truth is described as Brahman, Paramatma, and Bhagavan — the impersonal absolute, the inner witness, and the personal Lord. These are not three separate beings but three ways of approaching the one Reality.",fact:"This teaching — Brahman/Paramatma/Bhagavan as one — is the Bhagavata's great synthesis, reconciling Advaita (non-dual), Yoga, and Bhakti schools. Guruvayurappan embodies all three: you can worship Him as the personal Lord, meditate on Him as the inner Self, or contemplate Him as infinite Consciousness."},
{n:99,t:"Bhattathiri's Prayer",kv:"99.8",vt:"rogān apaharasva — I composed this summary of the Bhagavata at Your feet, O Guruvayurappa. My body is broken, my nerves fail. But my mind sees only You. Remove this disease, give me health to serve You — or take me to Vaikuntha. Either way, I am Yours.",q:"What was the condition under which Bhattathiri composed the Narayaneeyam?",o:["In perfect health as a celebration of the Lord","In severe paralysis and illness at Guruvayur — he composed it as both a prayer for healing and an offering of pure devotion, surrendering both health and death to the Lord's will","After a vision commanded him to","During a long pilgrimage"],a:1,vs:"रोगान् अपहरस्व मे गुरुवायुपुरेश्वर करुणाकर।",exp:"Meppathur Narayana Bhattathiri was struck by severe rheumatism (paralysis). Confined and suffering, he came to Guruvayur and composed the 1036-verse Narayaneeyam in 100 Dasakams. His prayer is unique: Give me health to serve You — or take me to You in death. I accept either with equal heart.",fact:"Tradition holds that when Bhattathiri completed the 100th Dasakam, the Lord of Guruvayur appeared and his disease was cured. The final verse of Dasakam 100 describes exactly the form in which the Lord appeared — making it both a prayer and a vision."},
{n:100,t:"Phala Shruti — Vision of Guruvayurappan",kv:"100.11",vt:"āyur ārogya saukhyam — May I always see that form: dark as rain clouds, eyes like the blue lotus, the gentle smile, four arms with conch and disc. This vision itself is liberation. Bhattathiri laid down his pen — for there is nothing left to say when God stands before you.",q:"What is the specific four-armed form of the Lord described in the final Dasakam 100?",o:["A two-armed form with flute like in Vrindavan","The four-armed form: dark-hued like rain clouds, lotus eyes, gentle smile, yellow silk, holding conch Panchajanya, discus Sudarshana, mace Kaumodaki, and lotus, adorned with Kaustubha gem and Tulasi garland, Lakshmi on His chest","The cosmic Vishwarupa form","The child form as in the Damodara lila"],a:1,vs:"आयुरारोग्यसौख्यं देहि देहीश गुरुवायुपुरवासिन्।",exp:"The final Dasakam gives the complete darshana description of Guruvayurappan: dark-hued (shyama), lotus eyes, gentle smile, yellow silk (pitambara), four arms holding the divine weapons, Kaustubha gem, Vanamala, Tulasi, Srivatsa mark, Lakshmi on the chest — the complete Bhagavan in His most gracious form.",fact:"Dasakam 100's final verse ends with the word Vata referring to Guruvayur's breeze — the Lord of the holy wind-god's abode. The poem begins and ends at Guruvayur, a perfect circle. This final verse was composed after the Lord appeared and healed Bhattathiri."},
];

const ALL = [...D1, ...D2];

// ── STYLES ────────────────────────────────────────────────────────────────────
const G = "#b8860b", DG = "#9a7209", BG = "#faf8f4";
const PA = "rgba(0,0,0,0.02)", BO = "rgba(180,140,60,0.2)";
const SAFFRON = "#d47a2e", LOTUS = "#c05070", TEAL = "#2a8a82", VIOLET = "#7a6aaa", RUBY = "#c04040";
const OPT_COLORS = ["#b8860b","#2a8a82","#c05070","#7a6aaa"];

const s = {
  root:{minHeight:"100vh",background:BG,fontFamily:"Georgia,serif",color:"#2a2018",position:"relative"},
  bg:{position:"fixed",top:0,left:0,right:0,bottom:0,background:"radial-gradient(ellipse at 20% 10%, rgba(220,170,60,0.06) 0%, transparent 40%), radial-gradient(ellipse at 80% 90%, rgba(120,80,180,0.04) 0%, transparent 50%), radial-gradient(ellipse at 50% 50%, rgba(40,140,130,0.03) 0%, transparent 60%)",pointerEvents:"none",zIndex:0},
  wrap:{position:"relative",zIndex:1,maxWidth:640,margin:"0 auto",padding:"20px 16px 60px"},
  om:{fontSize:72,lineHeight:1,color:SAFFRON,textShadow:"0 0 40px rgba(212,122,46,0.25)",textAlign:"center"},
  h1:{fontSize:28,fontWeight:"bold",textAlign:"center",color:G,margin:"8px 0 0"},
  sub:{fontSize:15,color:"#6a5a40",textAlign:"center",margin:"4px 0"},
  byline:{fontSize:12,color:"#8a7a9a",textAlign:"center",fontStyle:"italic",margin:0},
  statsBar:{display:"flex",gap:8,flexWrap:"wrap",justifyContent:"center",margin:"16px 0"},
  statBox:{borderRadius:10,padding:"8px 14px",textAlign:"center",minWidth:65},
  sv:{fontSize:20,fontWeight:"bold"},
  sl:{fontSize:10,marginTop:2},
  btnP:{background:`linear-gradient(135deg,${SAFFRON},${G})`,color:"#fff",border:"none",borderRadius:12,padding:"13px 28px",fontSize:14,fontWeight:"bold",cursor:"pointer",fontFamily:"Georgia,serif",boxShadow:"0 4px 16px rgba(212,122,46,0.25)"},
  btnS:{background:"transparent",color:G,border:`1px solid ${BO}`,borderRadius:12,padding:"11px 20px",fontSize:13,cursor:"pointer",fontFamily:"Georgia,serif"},
  row:{display:"flex",gap:10,flexWrap:"wrap",justifyContent:"center",margin:"4px 0"},
  foot:{fontSize:12,color:"#b0a090",textAlign:"center",marginTop:12},
  back:{background:"transparent",color:G,border:`1px solid ${BO}`,borderRadius:8,padding:"7px 14px",fontSize:12,cursor:"pointer",fontFamily:"Georgia,serif",marginBottom:14},
  ptit:{fontSize:22,color:G,textAlign:"center",margin:"0 0 14px"},
  inp:{width:"100%",background:"#fff",border:`1px solid ${BO}`,borderRadius:10,padding:"9px 14px",color:"#2a2018",fontSize:13,fontFamily:"Georgia,serif",boxSizing:"border-box",marginBottom:10,outline:"none"},
  frow:{display:"flex",flexWrap:"wrap",gap:6,marginBottom:10},
  fb:{background:PA,border:`1px solid ${BO}`,borderRadius:16,padding:"5px 12px",fontSize:11,color:"#6a5a40",cursor:"pointer",fontFamily:"Georgia,serif"},
  fba:{background:G,color:"#fff",borderColor:G,fontWeight:"bold"},
  grid:{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(145px,1fr))",gap:8},
  card:{background:"#fff",border:`1px solid ${BO}`,borderRadius:10,padding:"10px",cursor:"pointer",textAlign:"left",display:"flex",flexDirection:"column",gap:3,position:"relative",fontFamily:"Georgia,serif",color:"#2a2018"},
  cdone:{background:"rgba(42,138,130,0.06)",borderColor:"rgba(42,138,130,0.3)"},
  hdr:{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14},
  chip:{background:"rgba(122,106,170,0.1)",border:"1px solid rgba(122,106,170,0.25)",borderRadius:16,padding:"5px 12px",fontSize:12,color:VIOLET},
  banner:{background:"linear-gradient(135deg, rgba(212,122,46,0.06), rgba(122,106,170,0.04))",border:`1px solid ${BO}`,borderRadius:12,padding:"14px 16px",marginBottom:10},
  vbtn:{background:"rgba(42,138,130,0.06)",border:"1px solid rgba(42,138,130,0.2)",borderRadius:8,padding:"7px 14px",fontSize:12,color:TEAL,cursor:"pointer",fontFamily:"Georgia,serif",marginBottom:8},
  vbox:{background:"rgba(42,138,130,0.04)",border:"1px solid rgba(42,138,130,0.15)",borderRadius:10,padding:"14px",marginBottom:12,borderLeft:`4px solid ${TEAL}`},
  qbox:{background:"#fff",border:"1px solid rgba(0,0,0,0.08)",borderRadius:14,padding:"18px",boxShadow:"0 2px 12px rgba(0,0,0,0.04)"},
  qt:{fontSize:15,lineHeight:1.7,color:"#2a2018",marginBottom:16,fontWeight:"500"},
  opts:{display:"flex",flexDirection:"column",gap:8},
  opt:{background:"#faf8f4",border:"1px solid rgba(0,0,0,0.08)",borderRadius:10,padding:"12px 14px",textAlign:"left",cursor:"pointer",color:"#3a3028",fontSize:13,display:"flex",gap:10,alignItems:"center",fontFamily:"Georgia,serif",transition:"all 0.15s"},
  oc:{background:"rgba(42,138,80,0.1)",borderColor:"rgba(42,138,80,0.4)",color:"#1a6a30"},
  ow:{background:"rgba(192,64,64,0.08)",borderColor:"rgba(192,64,64,0.3)",color:"#a03030"},
  ol:{fontSize:11,width:24,height:24,minWidth:24,borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:"bold"},
  rbox:{marginTop:16,background:"linear-gradient(135deg, rgba(212,122,46,0.04), rgba(122,106,170,0.03))",border:`1px solid ${BO}`,borderRadius:12,padding:"16px"},
  rh:{fontSize:16,fontWeight:"bold",marginBottom:8},
  exp:{fontSize:13,color:"#4a3a28",lineHeight:1.7,marginBottom:10},
  ff:{background:"rgba(42,138,130,0.04)",border:"1px solid rgba(42,138,130,0.12)",borderRadius:8,padding:"9px 12px",marginBottom:12},
  hi:{background:"#fff",border:"1px solid rgba(0,0,0,0.06)",borderRadius:9,padding:"10px 14px",display:"flex",flexDirection:"column",gap:3},
  groupBtn:{background:"#fff",border:"1px solid rgba(0,0,0,0.08)",borderRadius:12,padding:"10px 12px",cursor:"pointer",fontFamily:"Georgia,serif",display:"flex",flexDirection:"column",alignItems:"center",gap:3,transition:"all 0.2s",boxShadow:"0 1px 4px rgba(0,0,0,0.04)"},
  groupBtnOpen:{background:"rgba(184,134,11,0.06)",border:`1px solid ${BO}`},
  listCard:{width:"100%",background:"#fff",border:"1px solid rgba(0,0,0,0.06)",borderRadius:8,padding:"9px 12px",cursor:"pointer",textAlign:"left",fontFamily:"Georgia,serif",color:"#2a2018",transition:"all 0.15s"},
  listCardDone:{background:"rgba(42,138,130,0.04)",borderColor:"rgba(42,138,130,0.15)"},
};

// ── COMPONENT ─────────────────────────────────────────────────────────────────
export default function NarayaneeyamGame() {
  const load = (k, d) => { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch { return d; } };
  const save = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} };

  const [screen, setScreen] = useState("home");
  const [sel, setSel] = useState(null);
  const [ans, setAns] = useState(null);
  const [score, setScore] = useState(() => load("nm_score", 0));
  const [total, setTotal] = useState(() => load("nm_total", 0));
  const [streak, setStreak] = useState(() => load("nm_streak", 0));
  const [done, setDone] = useState(() => new Set(load("nm_done", [])));
  const [hist, setHist] = useState(() => load("nm_hist", []));
  const [filter, setFilter] = useState("all");
  const [search, setSearch] = useState("");
  const [verse, setVerse] = useState(false);
  const [qIdx, setQIdx] = useState(0);
  const EXTRA = {};

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(() => {});
    } else {
      document.exitFullscreen().catch(() => {});
    }
  }, []);

  const ranges = ["all","1-10","11-20","21-30","31-40","41-50","51-60","61-70","71-80","81-90","91-100"];

  const filtered = ALL.filter(d => {
    if (filter !== "all") {
      const [lo,hi] = filter.split("-").map(Number);
      if (d.n < lo || d.n > hi) return false;
    }
    if (search && !d.t.toLowerCase().includes(search.toLowerCase()) && !String(d.n).includes(search)) return false;
    return true;
  });

  function pick(d) {
    const questions = d.qs || [{q:d.q,o:d.o,a:d.a,exp:d.exp,fact:d.fact}];
    const qi = Math.floor(Math.random() * questions.length);
    const question = questions[qi];
    const correctText = question.o[question.a];
    const shuffled = [...question.o].sort(() => Math.random() - 0.5);
    setSel({ ...d, ...question, o: shuffled, a: shuffled.indexOf(correctText) });
    setAns(null); setVerse(false); setScreen("play");
  }
  function rand() { pick(ALL[Math.floor(Math.random()*ALL.length)]); }
  function next() { const i = ALL.findIndex(x=>x.n===sel.n); pick(ALL[(i+1)%ALL.length]); }
  function cont() { pick(sel); }

  function choose(i) {
    if (ans !== null) return;
    setAns(i);
    const ok = i === sel.a;
    const newScore = score + (ok ? 1 : 0);
    const newTotal = total + 1;
    const newStreak = ok ? streak + 1 : 0;
    const newDone = ok ? new Set([...done, sel.n]) : done;
    const newHist = [{n:sel.n,t:sel.t,ok}, ...hist].slice(0, 100);
    setScore(newScore); setTotal(newTotal); setStreak(newStreak);
    setDone(newDone); setHist(newHist);
    save("nm_score", newScore); save("nm_total", newTotal);
    save("nm_streak", newStreak); save("nm_done", [...newDone]);
    save("nm_hist", newHist);
  }

  const acc = total > 0 ? Math.round(score/total*100) : 0;

  // HOME
  if (screen === "home") return (
    <div style={s.root}><div style={s.bg}/>
      <div style={{...s.wrap,display:"flex",flexDirection:"column",alignItems:"center",gap:12,paddingTop:40}}>
        <button onClick={toggleFullScreen} style={{position:"absolute",top:16,right:16,fontSize:11,color:G,background:"transparent",border:`1px solid ${BO}`,borderRadius:8,padding:"5px 12px",cursor:"pointer",fontFamily:"Georgia,serif"}}>⛶ Full Screen</button>
        <div style={s.om}>ॐ</div>
        <h1 style={s.h1}>Śrīman Nārāyaṇīyam</h1>
        <p style={s.sub}>Quiz — All 100 Dasakams</p>
        <div style={{background:"linear-gradient(135deg, rgba(212,122,46,0.04), rgba(122,106,170,0.03), rgba(42,138,130,0.03))",border:"1px solid rgba(0,0,0,0.06)",borderRadius:12,padding:"14px 16px",margin:"8px 0 4px",maxWidth:440}}>
          <p style={{fontSize:12,color:"#5a4a38",lineHeight:1.7,margin:0,textAlign:"center"}}>
            Composed in 1586 CE by <span style={{color:SAFFRON}}>Meppathur Narayana Bhattathiri</span> at the Guruvayur temple, the Narayaneeyam distills the 18,000 verses of the Bhagavata Purana into <span style={{color:TEAL}}>100 Dasakams</span> (groups of ten verses). Written as a prayer for healing, it journeys from the Lord's cosmic nature through all His avataras to the sweetness of Krishna's lilas — a masterpiece of devotion, philosophy, and poetry.
          </p>
        </div>
        <div style={s.statsBar}>
          {[["Questions",total,SAFFRON,"rgba(212,122,46,0.06)","rgba(212,122,46,0.15)"],["Correct",score,TEAL,"rgba(42,138,130,0.06)","rgba(42,138,130,0.15)"],["Accuracy",acc+"%",VIOLET,"rgba(122,106,170,0.06)","rgba(122,106,170,0.15)"],["Streak",streak,LOTUS,"rgba(192,80,112,0.06)","rgba(192,80,112,0.15)"]].map(([l,v,c,bg,bd])=>(
            <div key={l} style={{...s.statBox,background:bg,border:`1px solid ${bd}`}}><div style={{...s.sv,color:c}}>{v}</div><div style={{...s.sl,color:c,opacity:0.6}}>{l}</div></div>
          ))}
        </div>
        <div style={s.row}>
          <button style={s.btnP} onClick={()=>setScreen("select")}>Begin Journey</button>
          <button style={s.btnS} onClick={rand}>🎲 Random</button>
        </div>
        {hist.length>0 && <button style={s.btnS} onClick={()=>setScreen("hist")}>View History</button>}
        {total>0 && <button style={{...s.btnS,fontSize:11,color:"#a08090",border:"1px solid rgba(160,100,130,0.2)",padding:"8px 16px"}} onClick={()=>{ if(window.confirm("Reset all scores and history?")){ setScore(0);setTotal(0);setStreak(0);setDone(new Set());setHist([]); ["nm_score","nm_total","nm_streak","nm_done","nm_hist"].forEach(k=>localStorage.removeItem(k)); } }}>Reset Progress</button>}
        <p style={s.foot}>Guruvayurappan Sharanam 🙏</p>
      </div>
    </div>
  );

  // HISTORY
  if (screen === "hist") return (
    <div style={s.root}><div style={s.bg}/>
      <div style={s.wrap}>
        <button style={s.back} onClick={()=>setScreen("home")}>← Back</button>
        <p style={s.ptit}>Session History</p>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {hist.map((h,i)=>(
            <div key={i} style={{...s.hi,borderLeft:`4px solid ${h.ok?G:"#c0392b"}`}}>
              <span style={{fontSize:10,color:G}}>Dasakam {h.n}</span>
              <span style={{fontSize:13,color:"#3a3028"}}>{h.t}</span>
              <span style={{fontSize:12,fontWeight:"bold",color:h.ok?G:"#e74c3c"}}>{h.ok?"✓ Correct":"✗ Wrong"}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  // SELECT
  if (screen === "select") {
    const groupRanges = ranges.filter(r => r !== "all");
    const groupTints = ["#b8860b","#2e8b57","#3a7ec0","#c05070","#7a6a40","#2a8a82","#c87830","#7a6aaa","#8a7a30","#3a8a6a"];
    return (
    <div style={s.root}><div style={s.bg}/>
      <div style={s.wrap}>
        <button style={s.back} onClick={()=>setScreen("home")}>← Home</button>
        <p style={{...s.ptit,fontSize:18,marginBottom:10}}>Choose a Dasakam Group</p>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
          {groupRanges.map((r,ri) => {
            const [lo,hi] = r.split("-").map(Number);
            const group = ALL.filter(d => d.n >= lo && d.n <= hi);
            const doneCount = group.filter(d => done.has(d.n)).length;
            const tint = groupTints[ri] || G;
            return (
              <button key={r} style={s.groupBtn} onClick={()=>{setFilter(r);setScreen("group")}}>
                <span style={{fontSize:13,fontWeight:"bold",color:tint}}>{r}</span>
                <div style={{width:"100%",height:3,borderRadius:2,background:"rgba(0,0,0,0.06)",overflow:"hidden"}}>
                  <div style={{width:`${doneCount/group.length*100}%`,height:"100%",borderRadius:2,background:tint,opacity:0.5,transition:"width 0.3s"}}/>
                </div>
                <span style={{fontSize:9,color:"#8a8a8a"}}>{doneCount}/{group.length}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
    );
  }

  // GROUP — shows the 10 dasakams with Sanskrit verse and meaning
  if (screen === "group" && filter !== "all") {
    const groupRanges = ranges.filter(r => r !== "all");
    const groupTints = ["#b8860b","#2e8b57","#3a7ec0","#c05070","#7a6a40","#2a8a82","#c87830","#7a6aaa","#8a7a30","#3a8a6a"];
    const ri = groupRanges.indexOf(filter);
    const tint = groupTints[ri] || G;
    const [lo,hi] = filter.split("-").map(Number);
    const group = ALL.filter(d => d.n >= lo && d.n <= hi);
    return (
    <div style={s.root}><div style={s.bg}/>
      <div style={s.wrap}>
        <button style={s.back} onClick={()=>setScreen("select")}>← Back</button>
        <p style={{...s.ptit,fontSize:20,marginBottom:16,color:tint}}>Dasakams {filter}</p>
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          {group.map(d => (
            <div key={d.n} style={{background:"#fff",border:"1px solid rgba(0,0,0,0.06)",borderRadius:12,padding:"14px 16px",borderLeft:`4px solid ${tint}`,cursor:"pointer",boxShadow:"0 1px 6px rgba(0,0,0,0.04)"}} onClick={()=>pick(d)}>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:8}}>
                <span style={{fontSize:16,fontWeight:"bold",color:tint,minWidth:28}}>{d.n}</span>
                <span style={{fontSize:14,color:"#2a2018",fontWeight:"bold"}}>{d.t}</span>
                {done.has(d.n)&&<span style={{marginLeft:"auto",color:TEAL,fontSize:12}}>✓</span>}
              </div>
              <p style={{fontSize:15,color:"#6a5a40",lineHeight:1.9,margin:"0 0 8px",fontFamily:"serif",fontStyle:"italic"}}>{d.vs}</p>
              <p style={{fontSize:12,color:"#8a7a60",lineHeight:1.6,margin:0}}>{d.vt.split("—")[1]?.trim() || d.vt.split("—")[0].trim()}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
    );
  }

  // PLAY
  if (screen === "play" && sel) return (
    <div style={s.root}><div style={s.bg}/>
      <div style={s.wrap}>
        <div style={s.hdr}>
          <button style={s.back} onClick={()=>setScreen("select")}>← Dasakams</button>
          <div style={{display:"flex",gap:8,alignItems:"center"}}>
            <div style={s.chip}>🔥 {streak} | ✓ {score}/{total}</div>

          </div>
        </div>
        <div style={s.banner}>
          <div style={{fontSize:10,color:DG,letterSpacing:2,textTransform:"uppercase"}}>Dasakam {sel.n}</div>
          <div style={{fontSize:17,color:G,fontWeight:"bold"}}>{sel.t}</div>
        </div>
        <button style={s.vbtn} onClick={()=>setVerse(v=>!v)}>
          {verse?"Hide":"✨ Show"} Key Verse ({sel.kv})
        </button>
        {verse&&(
          <div style={s.vbox}>
            <div style={{fontSize:10,color:G,letterSpacing:1,marginBottom:7}}>✦ Key Verse {sel.kv}</div>
            <p style={{fontSize:13,color:"#5a4a38",lineHeight:1.8,margin:0,fontStyle:"italic"}}>{sel.vt}</p>
          </div>
        )}
        <div style={s.qbox}>
          <p style={s.qt}>{sel.q}</p>
          <div style={s.opts}>
            {sel.o.map((opt,i)=>{
              let style = s.opt;
              if (ans!==null) {
                if (i===sel.a) style={...s.opt,...s.oc};
                else if (i===ans) style={...s.opt,...s.ow};
                else style={...s.opt,opacity:0.4};
              }
              const optColor = OPT_COLORS[i];
              return (
                <button key={i} style={style} onClick={()=>choose(i)}>
                  <span style={{...s.ol,background:`${optColor}20`,color:optColor}}>{["A","B","C","D"][i]}</span>
                  <span>{opt}</span>
                </button>
              );
            })}
          </div>
          {ans!==null&&(
            <div style={s.rbox}>
              <div style={{...s.rh,color:ans===sel.a?TEAL:SAFFRON}}>{ans===sel.a?"✨ Excellent!":"📖 Learn & Grow"}</div>
              <p style={s.exp}>{sel.exp}</p>
              {sel.vs&&<div style={{background:"linear-gradient(135deg, rgba(212,122,46,0.05), rgba(122,106,170,0.03))",border:"1px solid rgba(212,122,46,0.15)",borderLeft:`4px solid ${SAFFRON}`,borderRadius:8,padding:"12px 14px",marginBottom:10}}>
                <div style={{fontSize:10,color:SAFFRON,letterSpacing:1,marginBottom:8}}>✦ Key Verse {sel.kv}</div>
                <p style={{fontSize:16,color:"#5a4020",lineHeight:2,margin:"0 0 8px",fontFamily:"serif"}}>{sel.vs}</p>
                <p style={{fontSize:11,color:"#7a6a50",lineHeight:1.6,margin:0,fontStyle:"italic"}}>{sel.vt}</p>
              </div>}
              <div style={s.ff}>
                <span style={{color:TEAL,fontSize:12,fontWeight:"bold"}}>💡 Insight: </span>
                <span style={{color:"#5a5040",fontSize:12}}>{sel.fact}</span>
              </div>
              <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                <button style={s.btnP} onClick={cont}>↺ Try Again</button>
                <button style={s.btnP} onClick={next}>Next →</button>
                <button style={s.btnS} onClick={rand}>🎲</button>
                <button style={s.btnS} onClick={()=>setScreen("select")}>≡</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );

  return null;
}
